-- Priest offense only: restore/support amounts never use these multipliers.
function HopePriest_BaseDamage(amount)
	return amount * 0.8
end
function HopePriest_TargetDamage(amount, target)
	if IsUnitType(target, UNIT_TYPE_UNDEAD) then
		return amount * 1.25
	end
