-- Camera and selection changes are client-local; gameplay state stays synchronized.
-- ResetToGameCamera releases a previous unit controller, but also resets the lens.
-- Keep every view field so F3, room changes and unlocking never force a new zoom.
function HopeCamera_ResetKeepView()
	local distance = GetCameraField(CAMERA_FIELD_TARGET_DISTANCE)
	local attack = Rad2Deg(GetCameraField(CAMERA_FIELD_ANGLE_OF_ATTACK))
	local rotation = Rad2Deg(GetCameraField(CAMERA_FIELD_ROTATION))
	local roll = Rad2Deg(GetCameraField(CAMERA_FIELD_ROLL))
	local fov = Rad2Deg(GetCameraField(CAMERA_FIELD_FIELD_OF_VIEW))
	local z = GetCameraField(CAMERA_FIELD_ZOFFSET)
	local farz = GetCameraField(CAMERA_FIELD_FARZ)
	ResetToGameCamera(0.0)
	SetCameraField(CAMERA_FIELD_TARGET_DISTANCE, distance, 0.0)
	SetCameraField(CAMERA_FIELD_ANGLE_OF_ATTACK, attack, 0.0)
	SetCameraField(CAMERA_FIELD_ROTATION, rotation, 0.0)
	SetCameraField(CAMERA_FIELD_ROLL, roll, 0.0)
	SetCameraField(CAMERA_FIELD_FIELD_OF_VIEW, fov, 0.0)
	SetCameraField(CAMERA_FIELD_ZOFFSET, z, 0.0)
	SetCameraField(CAMERA_FIELD_FARZ, farz, 0.0)
end

function HopeCamera_FocusUnit(p, u, follow)
	if p == GetLocalPlayer() and u ~= nil and GetUnitTypeId(u) ~= 0 then
		HopeCamera_ResetKeepView()
		ClearSelection()
		SelectUnit(u, true)
		PanCameraToTimed(GetUnitX(u), GetUnitY(u), 0.0)
		if follow then
			SetCameraTargetController(u, 0.0, 0.0, false)
		end
	end
end

function HopeMini_Focus(p)
	HopeCamera_FocusUnit(p, HopeMini_Actor[GetPlayerId(p) + 1], true)
end

-- The generic room-entry callback runs after the minigame creation trigger.
-- It must not pan back to the old, inactive hero after a minigame actor exists.
function HopeCamera_EnterRoom(p)
	if HopeMini_Actor[GetPlayerId(p) + 1] ~= nil then
		HopeMini_Focus(p)
	else
		HopeCamera_FocusUnit(p, udg_hero[GetPlayerId(p) + 1], LoadBoolean(YDHT, GetHandleId(udg_hero[GetPlayerId(p) + 1]), 2039566794))
	end
end

-- One synchronized next-frame correction handles same-frame camera transitions.
-- Do not keep recentering every UI tick: players can still inspect the arena.
function HopeMini_FocusAfterEntry()
	local t = GetExpiredTimer()
	local p = LoadPlayerHandle(YDHT, GetHandleId(t), 0)
	local u = LoadUnitHandle(YDHT, GetHandleId(t), 1)
	if u ~= nil and HopeMini_Actor[GetPlayerId(p) + 1] == u and GetUnitTypeId(u) ~= 0 then
		HopeMini_Focus(p)
	end
	FlushChildHashtable(YDHT, GetHandleId(t))
	DestroyTimer(t)
	u = nil
	p = nil
	t = nil
end

function HopeMini_Attach(p, u)
	local t = nil
	HopeMini_Actor[GetPlayerId(p) + 1] = u
	SaveBoolean(YDHT, GetHandleId(udg_hero[GetPlayerId(p) + 1]), 2039566794, false)
	HopeMini_Focus(p)
	if u ~= nil then
		t = CreateTimer()
		SavePlayerHandle(YDHT, GetHandleId(t), 0, p)
		SaveUnitHandle(YDHT, GetHandleId(t), 1, u)
		TimerStart(t, 0.03, false, HopeMini_FocusAfterEntry)
	end
	t = nil
end

function HopeMini_Detach(p)
	HopeMini_Actor[GetPlayerId(p) + 1] = nil
	HopeCamera_FocusUnit(p, udg_hero[GetPlayerId(p) + 1], false)
end

-- A02U poison has six separate source stacks in the original enemy hashtable.
-- These getters never infer damage from the sum or mutate any combat state.
function HopeStatus_Init()
	if HopeStatus_History == nil then
		HopeStatus_History = InitHashtable()
	end
end

function HopeStatus_ClearHistory(u)
	if HopeStatus_History ~= nil and u ~= nil then
		FlushChildHashtable(HopeStatus_History, GetHandleId(u))
	end
end

function HopeStatus_RecordPoison(u, amount)
	if HopeStatus_History ~= nil and u ~= nil and GetUnitTypeId(u) ~= 0 and IsUnitAliveBJ(u) then
		SaveReal(HopeStatus_History, GetHandleId(u), 1, RMaxBJ(0.0, amount))
		SaveInteger(HopeStatus_History, GetHandleId(u), 2, udg_huihe_s)
	end
end

-- Format only after the real calculation; never cast large damage to integer.
function HopeStatus_Number(value)
	local magnitude = RAbsBJ(value)
	-- Avoid real literals whose integer part exceeds signed-32-bit validation.
	-- Build this unit from safe real operands; never write a trillion literal.
	local trillion = 100000000.0 * 10000.0
	if magnitude >= trillion then
		return (R2SW(value / trillion, 1, 1) or "") .. "万亿"
	elseif magnitude >= 100000000.0 then
		return (R2SW(value / 100000000.0, 1, 1) or "") .. "亿"
	elseif magnitude >= 10000.0 then
		return (R2SW(value / 10000.0, 1, 1) or "") .. "万"
	elseif value == I2R(R2I(value)) then
		return I2S(R2I(value))
	elseif magnitude < 0.001 then
		if value > 0.0 then
			return "<0.001"
		end
		return ">-0.001"
	elseif magnitude < 0.01 then
		return R2SW(value, 1, 3)
	elseif magnitude < 0.1 then
		return R2SW(value, 1, 2)
	end
	return R2SW(value, 1, 1)
end

function HopeStatus_PoisonLastLine(u)
	if HopeStatus_History == nil or u == nil then
		return ""
	end
	if not HaveSavedReal(HopeStatus_History, GetHandleId(u), 1) then
		return ""
	end
	return "上次毒结算净扣血 " .. (HopeStatus_Number(LoadReal(HopeStatus_History, GetHandleId(u), 1)) or "")
end

function HopeStatus_PoisonKey(playerIndex)
	if playerIndex == 0 then
		return -374736685
	elseif playerIndex == 1 then
		return 806467174
	elseif playerIndex == 2 then
		return 370822118
	elseif playerIndex == 3 then
		return 67668322
	elseif playerIndex == 4 then
		return -1058892367
	elseif playerIndex == 5 then
		return 1622058564
	end
	return 0
end

function HopeStatus_PoisonCount(u, playerIndex)
	local count = 0
	if u == nil or playerIndex < 0 or playerIndex >= 6 then
		return 0
	end
	if GetUnitTypeId(u) == 0 or not IsUnitAliveBJ(u) then
		return 0
	end
	count = LoadInteger(YDHT, GetHandleId(u), HopeStatus_PoisonKey(playerIndex))
	if count < 0 then
		return 0
	end
	return count
end

function HopeStatus_PoisonTotal(u)
	local i = 0
	local total = 0
	for _ in _loop_() do
		if i >= 6 then break end
		total = total + HopeStatus_PoisonCount(u, i)
		i = i + 1
	end
	return total
end

function HopeStatus_PoisonSourceBase(u, playerIndex)
	local count = HopeStatus_PoisonCount(u, playerIndex)
	local amount = 0.0
	local source = nil
	if count <= 0 then
		return 0.0
	end
	source = udg_hero[playerIndex + 1]
	if source ~= nil then
		amount = I2R(count) * GetUnitState(source, ConvertUnitState(20)) * 0.3 * I2R(GetUnitAbilityLevel(source, 1093677653))
	end
	source = nil
	if amount <= 0.0 then
		return 0.0
	end
	return amount
end

-- The exact sum of the six original pre-engine damage calls at current stats.
-- Final health loss may also depend on native mitigation and damage triggers.
function HopeStatus_PoisonBase(u)
	local i = 0
	local amount = 0.0
	for _ in _loop_() do
		if i >= 6 then break end
		amount = amount + HopeStatus_PoisonSourceBase(u, i)
		i = i + 1
	end
	return amount
end

-- Known script multipliers only. Native armor/immune rules and asynchronous
-- follow-up strikes are deliberately not represented as guaranteed HP loss.
function HopeStatus_PoisonSourceReference(u, playerIndex, upper)
	local normal = HopeStatus_PoisonSourceBase(u, playerIndex)
	local critical = 0.0
	local chance = 0
	if normal <= 0.0 then
		return 0.0
	end
	normal = RMaxBJ(0.0, normal * udg_Zuizhong_Dm[playerIndex + 1] * (1.0 - LoadReal(YDHT, GetHandleId(u), 877254238)))
	chance = udg_Baoji_Lv[playerIndex + 1]
	critical = RMaxBJ(0.0, normal * udg_Baoji_Damage[playerIndex + 1] * HopeMeta_Out(playerIndex, false, HopeCoop_IsBoss(u), true))
	normal = normal * HopeMeta_Out(playerIndex, false, HopeCoop_IsBoss(u), false)
	if chance <= 0 then
		return normal
	elseif chance >= 100 then
		return critical
	elseif upper then
		return RMaxBJ(normal, critical)
	end
	return RMinBJ(normal, critical)
end

function HopeStatus_PoisonReference(u, upper)
	local i = 0
	local amount = 0.0
	for _ in _loop_() do
		if i >= 6 then break end
		amount = amount + HopeStatus_PoisonSourceReference(u, i, upper)
		i = i + 1
	end
	return amount
end

function HopeStatus_PoisonRange(u, compact)
	local low = HopeStatus_PoisonReference(u, false)
	local high = HopeStatus_PoisonReference(u, true)
	local left = ""
	local right = ""
	left = HopeStatus_Number(low)
	right = HopeStatus_Number(high)
	if left == right then
		return left
	end
	-- KK fonts may omit the en dash and join both values.
	return (left or "") .. " 至 " .. (right or "")
end

function HopeStatus_PoisonPreviewLine(u)
	if HopeStatus_PoisonTotal(u) <= 0 then
		return ""
	end
	return "本轮毒伤参考 " .. (HopeStatus_PoisonRange(u, false) or "")
end

function HopeStatus_PoisonBaseText(u)
