end

function HopeStatus_PoisonDetails(u, p)
	local total = HopeStatus_PoisonTotal(u)
	local own = HopeStatus_PoisonCount(u, GetPlayerId(p))
	if total <= 0 then
		return ""
	end
	return "|cff8be28b中毒合计 " .. (I2S(total) or "") .. " 层|r · 你的 " .. (I2S(own) or "") .. " 层"
end

-- Presentation-only armor reduction history. Original combat setters remain in place.
-- Reuse the status display table; keys 1/2 belong to observed poison history.
-- Spawn/death/room-exit display cleanup removes the entire per-unit child table.
function HopeDebuff_RecordArmor(u, beforeArmor)
	local reduced = 0.0
	if HopeStatus_History ~= nil and u ~= nil and GetUnitTypeId(u) ~= 0 and IsUnitAliveBJ(u) then
		reduced = beforeArmor - GetUnitState(u, ConvertUnitState(32))
		if reduced > 1e-05 then
			SaveReal(HopeStatus_History, GetHandleId(u), 3, LoadReal(HopeStatus_History, GetHandleId(u), 3) + reduced)
		end
	end
end

function HopeDebuff_ClearArmor(u)
	if HopeStatus_History ~= nil and u ~= nil then
		RemoveSavedReal(HopeStatus_History, GetHandleId(u), 3)
	end
end

function HopeDebuff_Armor(u)
	if HopeStatus_History == nil or u == nil or GetUnitTypeId(u) == 0 or not IsUnitAliveBJ(u) then
		return 0.0
	end
	return LoadReal(HopeStatus_History, GetHandleId(u), 3)
end

function HopeDebuff_Weakened(u)
	if u == nil or GetUnitTypeId(u) == 0 or not IsUnitAliveBJ(u) then
		return false
	end
	-- A canceled attack is already represented by the original intent kind "1".
	return LoadStr(YDHT, GetHandleId(u), -1661751302) == "attack" and LoadBoolean(YDHT, GetHandleId(u), 240964279)
end

function HopeDebuff_Number(value)
	if RAbsBJ(value - I2R(R2I(value))) < 1e-05 then
		return I2S(R2I(value))
	end
	return R2SW(value, 1, 1)
end

function HopeDebuff_Lines(u)
	local count = 0
	if HopeDebuff_Armor(u) > 1e-05 then
		count = count + 1
	end
	if HopeDebuff_Weakened(u) then
		count = count + 1
	end
	return count
end

function HopeDebuff_Details(u)
	local text = ""
	local reduced = HopeDebuff_Armor(u)
	if reduced > 1e-05 then
		text = "|cffffc58b破甲 -" .. (HopeDebuff_Number(reduced) or "") .. " · 当前甲 " .. (HopeDebuff_Number(GetUnitState(u, ConvertUnitState(32))) or "") .. "|r"
	end
	if HopeDebuff_Weakened(u) then
		if text ~= "" then
			text = (text or "") .. "|n"
		end
		text = (text or "") .. "|cffffc58b虚弱 · 下次攻击 -30%|r"
	end
	return text
end

-- One persistent label per real combat enemy. Never recreate it on selection.
-- No speculative targeting, RNG, orders or writes to the original intent data.
function HopeIntent_SetPhase(u, phase)
	if HopeStatus_History ~= nil and u ~= nil and GetUnitTypeId(u) ~= 0 and IsUnitAliveBJ(u) and GetOwningPlayer(u) == Player(11) then
		SaveInteger(HopeStatus_History, GetHandleId(u), 4, phase)
	end
end

-- Original overhead labels truncate the displayed value, not combat state.
-- Keep R2I inside a safe range. Larger native reals have no fractional precision.
function HopeIntent_Number(value)
	if RAbsBJ(value) < 1000000000.0 then
		return I2S(R2I(value))
	end
	return R2SW(value, 1, 0)
end

function HopeIntent_SignedNumber(value)
	if value < 0.0 then
		return HopeIntent_Number(value)
	end
	return "+" .. (HopeIntent_Number(value) or "")
end

function HopeIntent_PlayerLabel(p)
	return HopeName_Label(p, 70)
end

function HopeIntent_Headline(u)
	local kind = LoadStr(YDHT, GetHandleId(u), -1661751302)
	local phase = LoadInteger(HopeStatus_History, GetHandleId(u), 4)
	local target = nil
	local owner = nil
	local name = "未定"
	local text = "|cffb9bec7待定|r"
	local poison = HopeStatus_PoisonTotal(u)
	local fallen = false
	if kind == "1" then
		text = "|cff9dd4b0打断|r"
	elseif phase == 2 then
		-- The original callback is one second after dispatch; delayed spells may remain.
		text = "|cffb9bec7已出手|r"
	elseif kind == "attack" then
		target = LoadUnitHandle(YDHT, GetHandleId(u), -272485038)
		if target ~= nil and GetUnitTypeId(target) ~= 0 then
			owner = GetOwningPlayer(target)
			if owner == GetLocalPlayer() then
				name = "你"
			else
				name = HopeIntent_PlayerLabel(owner)
			end
			fallen = not IsUnitAliveBJ(target)
			name = YDWEGetPlayerColorString(owner, name)
		end
		text = "|cffffce93攻击|r" .. (name or "") .. "|cffffce93(" .. (HopeIntent_Number(RMaxBJ(0.0, LoadReal(YDHT, GetHandleId(u), -1820993401))) or "") .. ")|r"
		if fallen then
			text = (text or "") .. "|cffb9bec7·倒下|r"
		end
	elseif kind == "skill" then
		if phase == 1 then
			text = "|cffe2b6ff施放中|r"
		else
			text = "|cffe2b6ff施法|r"
		end
	elseif kind == "defend" then
		text = "|cff9cdbff防御(DEF" .. (HopeIntent_SignedNumber(LoadReal(YDHT, GetHandleId(u), -1559201479)) or "") .. ")|r"
	elseif kind == "buff" then
		text = "|cffffdc87强化(ATK" .. (HopeIntent_SignedNumber(LoadReal(YDHT, GetHandleId(u), 400320547)) or "") .. ")|r"
	end
	if poison > 0 then
		text = (text or "") .. " · |cff99e5a0毒" .. (I2S(poison) or "") .. "|r"
	end
	target = nil
	owner = nil
	return text
end

function HopeIntent_Release(index)
	if HopeIntent_Tags[index] ~= nil then
		DestroyTextTag(HopeIntent_Tags[index])
	end
	HopeIntent_Tags[index] = nil
	HopeIntent_Units[index] = nil
	HopeIntent_LastText[index] = ""
end

function HopeIntent_Collect()
	local u = GetEnumUnit()
	local i = 1
	local slot = 0
	local tag = nil
	if u ~= nil and GetUnitTypeId(u) ~= 0 and IsUnitAliveBJ(u) and GetOwningPlayer(u) == Player(11) then
		for _ in _loop_() do
			if i > HopeIntent_Count or slot < 0 then break end
			if HopeIntent_Units[i] == u then
				slot =  - i
			elseif HopeIntent_Units[i] == nil and slot == 0 then
				slot = i
			end
			i = i + 1
		end
		if slot < 0 then
			slot =  - slot
		elseif slot == 0 then
			HopeIntent_Count = HopeIntent_Count + 1
			slot = HopeIntent_Count
		end
		HopeIntent_Units[slot] = u
		-- Retry a failed engine allocation on subsequent synchronized ticks.
		if HopeIntent_Tags[slot] == nil then
			tag = CreateTextTag()
			HopeIntent_Tags[slot] = tag
			if tag ~= nil then
				SetTextTagPermanent(tag, true)
				SetTextTagVelocity(tag, 0.0, 0.0)
				SetTextTagVisibility(tag, false)
				SetTextTagColor(tag, 255, 255, 255, 255)
				DzTextTagSetShadowColor(tag, 0)
				HopeIntent_LastText[slot] = ""
			end
		end
	end
	tag = nil
	u = nil
end

-- Keep the native anchor on the actual enemy. Avoidance may change only the
-- height among three bounded lanes, never world X/Y or screen-edge positions.
function HopeIntent_Place(index)
	local u = HopeIntent_Units[index]
	local tag = HopeIntent_Tags[index]
	local text = ""
	local x = GetUnitX(u)
	local y = GetUnitY(u)
	local dx = 0.0
	local dy = 0.0
	local j = 1
	local lane = 0
	local used0 = false
	local used1 = false
	local used2 = false
	local visible = IsUnitVisible(u, GetLocalPlayer()) and HopeMini_Actor[GetPlayerId(GetLocalPlayer()) + 1] == nil
	HopeIntent_Placed[index] = false
	if tag == nil then
		u = nil
		return
	end
	SetTextTagVisibility(tag, visible)
	if not visible then
		u = nil
		tag = nil
		return
	end
	text = HopeIntent_Headline(u)
	if text ~= HopeIntent_LastText[index] then
		SetTextTagTextBJ(tag, text, 7.0)
		HopeIntent_LastText[index] = text
	end
	-- Only immediate world-space neighbors can reserve a lane. The tag remains
	-- attached even for a very dense summon pile; extra units reuse these lanes.
	for _ in _loop_() do
		if j >= index then break end
		if HopeIntent_Placed[j] then
			dx = x - HopeIntent_X[j]
			dy = y - HopeIntent_Y[j]
			if dx * dx + dy * dy <= 57600.0 then
				if HopeIntent_Lane[j] == 0 then
					used0 = true
				elseif HopeIntent_Lane[j] == 1 then
					used1 = true
				else
					used2 = true
				end
			end
		end
		j = j + 1
	end
	if not used0 then
		lane = 0
	elseif not used1 then
		lane = 1
	elseif not used2 then
		lane = 2
	else
		lane = ModuloInteger(index - 1, 3)
	end
	HopeIntent_X[index] = x
	HopeIntent_Y[index] = y
	HopeIntent_Lane[index] = lane
	HopeIntent_Placed[index] = true
	SetTextTagPosUnit(tag, u, 70.0 + 24.0 * I2R(lane))
	tag = nil
	u = nil
end

function HopeIntent_RefreshAll()
	local i = 1
	local combat = udg_ZhandouZhong and udg_Guaiwu_dwz ~= nil
	-- Everything through collection is synchronized, including hidden enemies.
	for _ in _loop_() do
		if i > HopeIntent_Count then break end
		if HopeIntent_Units[i] ~= nil then
			if not combat or GetUnitTypeId(HopeIntent_Units[i]) == 0 or not IsUnitAliveBJ(HopeIntent_Units[i]) or GetOwningPlayer(HopeIntent_Units[i]) ~= Player(11) or not IsUnitInGroup(HopeIntent_Units[i], udg_Guaiwu_dwz) then
				HopeIntent_Release(i)
			end
		end
		HopeIntent_Placed[i] = false
		i = i + 1
	end
	if combat then
		ForGroup(udg_Guaiwu_dwz, HopeIntent_Collect)
	end
	for _ in _loop_() do
		if HopeIntent_Count <= 0 or HopeIntent_Units[HopeIntent_Count] ~= nil then break end
		HopeIntent_Count = HopeIntent_Count - 1
	end
	i = 1
	for _ in _loop_() do
		if i > HopeIntent_Count then break end
		if HopeIntent_Units[i] ~= nil then
			HopeIntent_Place(i)
		end
		i = i + 1
	end
end

function HopeTurn_CanEnd(p)
	local i = GetPlayerId(p) + 1
	local u = udg_hero[i]
	local result = false
	if i >= 1 and i <= 6 and u ~= nil and HopeMini_Actor[i] == nil and udg_ZhandouZhong then
		result = GetOwningPlayer(u) == p and IsUnitAliveBJ(u) and not IsUnitPaused(u) and IsPlayerInForce(p, udg_WJZ_______weizhunbei) and RectContainsUnit(gg_rct______________000, u) and GetUnitAbilityLevel(u, 1093677105) > 0
	end
	u = nil
	return result
end

-- Synchronized UI event: issue the original ability order; never duplicate its effects.
function HopeTurn_EndClick()
	local p = DzGetTriggerUIEventPlayer()
	if HopeTurn_CanEnd(p) then
		if not IssueImmediateOrder(udg_hero[GetPlayerId(p) + 1], "stasistrap") then
			DisplayTextToPlayer(p, 0, 0, "暂时无法结束回合，请等当前动作完成后再试，或选中英雄按 G。")
		end
	end
	p = nil
end

function HopeTurn_Waiting()
	local i = 0
	local count = 0
	for _ in _loop_() do
		if i >= 6 then break end
		if GetPlayerSlotState(Player(i)) == PLAYER_SLOT_STATE_PLAYING and IsPlayerInForce(Player(i), udg_WJZ_______weizhunbei) and IsUnitAliveBJ(udg_hero[i + 1]) and not IsUnitPaused(udg_hero[i + 1]) then
			count = count + 1
		end
		i = i + 1
	end
	return count
end

