	if index == 0 then
		return "开局金币 +50|n力量 / 敏捷 / 智力各 +1"
	elseif index == 1 then
		return "开局金币 +50"
	elseif index == 2 then
		return "开局木材 +1"
	elseif index == 3 then
		return "开局木材 +1|n力量 / 敏捷 / 智力各 +1"
	elseif index == 4 then
