-- skill buttons, inventory, experience bar and their visibility hierarchy.
-- Preserve that complete hierarchy. Showing a child after HideInterface does
-- not restore its hidden parent, and restoring buttons alone loses unit info.
function HopeConsole_Init()
end

function HopeQoL_SelectHero()
	local u = udg_hero[GetPlayerId(GetLocalPlayer()) + 1]
	if HopeMini_Actor[GetPlayerId(GetLocalPlayer()) + 1] ~= nil then
		HopeMini_Focus(GetLocalPlayer())
		u = nil
		return
	end
	if u ~= nil then
		HopeCamera_FocusUnit(GetLocalPlayer(), u, LoadBoolean(YDHT, GetHandleId(u), 2039566794))
	end
	u = nil
end

function HopeQoL_SelectBag()
	local u = udg_Bei_bao_danwei[GetPlayerId(GetLocalPlayer()) + 1]
	if u ~= nil then
		HopeCamera_FocusUnit(GetLocalPlayer(), u, false)
	end
	u = nil
end

function HopeQoL_ToggleStats()
	if not HopeQoL_UIReady then
		DisplayTimedTextToPlayer(GetLocalPlayer(), 0, 0, 8.0, "属性窗体尚未就绪；稍后按 F4 重试，输入 -ui 查看状态。")
		return
	end
	HopeQoL_Expanded = not HopeQoL_Expanded
	if HopeQoL_Expanded then
		HopeLayout_Focus(1)
	end
	if HopeGrowth_Pending[GetPlayerId(GetLocalPlayer())] then
		HopeChoice_Hidden = true
	end
	HopeArchive_Expanded = false
	HopeGift_Expanded = false
	HopeRelic_Expanded = false
	HopeRoute_Details = false
end

function HopeQoL_CloseStats()
	HopeQoL_Expanded = false
end

function HopeQoL_ToggleHud()
	HopeQoL_Visible = not HopeQoL_Visible
end

function HopeIntent_Close()
	HopeIntent_Selected = nil
end

function HopeRoute_ToggleDetails()
	HopeRoute_Details = not HopeRoute_Details
	if HopeRoute_Details then
		HopeLayout_Focus(9)
	end
	if HopeRoute_Details then
		if HopeGrowth_Pending[GetPlayerId(GetLocalPlayer())] then
			HopeChoice_Hidden = true
		end
		HopeQoL_Expanded = false
		HopeArchive_Expanded = false
		HopeGift_Expanded = false
		HopeRelic_Expanded = false
	end
end

-- Compact labels retain UTF-8 characters; the full roster remains available.
-- The chat command -route continues to show every complete name.
function HopeRoute_CompactStatus()
	local i = 0
	local s = ""
	local name = ""
	local leader = HopeRoute_Leader()
	for _ in _loop_() do
		if i >= 6 then break end
		if HopeRoute_Active(i) then
			name = HopeName_Label(Player(i), 70)
			if i == leader then
				name = (name or "") .. "★"
			end
			if HopeRoute_RewardPending(i) then
				s = (s or "") .. (name or "") .. " |cffffc060待选择|r|n"
			elseif udg_hero[i + 1] == nil then
				s = (s or "") .. (name or "") .. " |cffaaaaaa初始化中|r|n"
			elseif HopeRoute_Ready[i] then
				s = (s or "") .. (name or "") .. " |cff80ef90已准备|r|n"
			else
				s = (s or "") .. (name or "") .. " |cffaaaaaa未准备|r|n"
			end
		end
		i = i + 1
	end
	return s
end

function HopeQoL_Slots(u)
	local i = 0
	local n = 0
	if u == nil then
		return 0
	end
	for _ in _loop_() do
		if i >= 6 then break end
		if UnitItemInSlot(u, i) ~= nil then
			n = n + 1
		end
		i = i + 1
	end
	return n
end

function HopeQoL_Number(r)
	return R2SW(r, 1, 1)
end

function HopeQoL_Growth(r)
	return R2SW(r, 1, 2)
end

-- Original six growth ratings (Trig______________009Actions), with their color
-- families lightened for readable text on the dark panel.
-- Life (7,8] originally inherited Intelligence's previous rating by mistake;
-- complete its S band as (7,9] without changing any growth value.
function HopeQoL_GrowthGrade(r, life)
	if life and r <= 3.0 or not life and r <= 0.9 then
		return "|cffaaaaaaE|r"
	elseif life and r <= 4.0 or not life and r <= 1.2 then
		return "|cfff1f1f1D|r"
	elseif life and r <= 5.0 or not life and r <= 1.6 then
		return "|cff80ef90C|r"
	elseif life and r <= 6.0 or not life and r <= 2.0 then
		return "|cff89c8ffB|r"
	elseif life and r <= 7.0 or not life and r <= 2.4 then
		return "|cffff9696A|r"
	elseif life and r <= 9.0 or not life and r <= 2.8 then
		return "|cffffc060S|r"
	end
	return "|cffffe066EX|r"
end

function HopeQoL_GradedGrowth(r, life)
	return (HopeQoL_Growth(r) or "") .. " " .. (HopeQoL_GrowthGrade(r, life) or "")
end

function HopeQoL_CompactNumber(r)
	if r == I2R(R2I(r)) then
		return I2S(R2I(r))
	end
	return HopeQoL_Number(r)
end

-- Refresh the legacy value for compatibility, but do not resurrect its duplicate overlay on F5.
function HopeQoL_RefreshLegacyAP()
	local p = GetPlayerId(GetLocalPlayer()) + 1
	if p >= 1 and p <= 6 and udg_xingdongdian_xs[p] ~= 0 then
		DzFrameSetText(udg_xingdongdian_xs[p], "行动点：" .. (I2S(udg_xingdong_dian[p]) or "") .. "/" .. (I2S(udg_xingdong_dianSx[p]) or ""))
		DzFrameShow(udg_xingdongdian_xs[p], not HopeQoL_UIReady)
	end
end

function HopeTeam_UpdateAP()
	local i = 1
	local u = nil
	local s = ""
	local show = false
	for _ in _loop_() do
		if i > 6 then break end
		u = udg_hero[i]
		show = udg_ZhandouZhong and HopeRoute_Active(i - 1) and Player(i - 1) ~= GetLocalPlayer() and u ~= nil and IsUnitAliveBJ(u) and IsUnitVisible(u, GetLocalPlayer()) and HopeMini_Actor[i] == nil
		SetTextTagVisibility(HopeTeam_APTag[i], show)
		if show then
			if IsPlayerInForce(Player(i - 1), udg_WJZ_______weizhunbei) then
				s = "行动 " .. (I2S(udg_xingdong_dian[i]) or "") .. "/" .. (I2S(udg_xingdong_dianSx[i]) or "")
				if IsUnitPaused(u) then
					s = (s or "") .. " · 进行中"
				end
				if udg_xingdong_dian[i] > 0 then
					SetTextTagColor(HopeTeam_APTag[i], 140, 240, 155, 255)
				else
					SetTextTagColor(HopeTeam_APTag[i], 255, 210, 105, 255)
				end
			elseif HopeTurn_Waiting() > 0 then
				s = "已结束"
				SetTextTagColor(HopeTeam_APTag[i], 180, 180, 180, 255)
			else
				s = "等待下回合"
				SetTextTagColor(HopeTeam_APTag[i], 180, 180, 180, 255)
			end
			SetTextTagTextBJ(HopeTeam_APTag[i], (HopeIntent_PlayerLabel(Player(i - 1)) or "") .. " · " .. (s or ""), 5.5)
			SetTextTagPosUnit(HopeTeam_APTag[i], u, 105.0)
		end
		i = i + 1
	end
	u = nil
end

-- Informational only: the original transition still draws the random result.
function HopeRoute_Title(node)
	local kind = GetUnitTypeId(node)
	if kind == 1848651849 then
		return "小怪关卡"
	elseif kind == 1848651850 then
		return "精英关卡"
	elseif kind == 1848651851 then
		return "装备商店"
	elseif kind == 1848651852 then
		return "随机关卡"
	elseif kind == 1848651853 then
		return "泉水关卡"
	elseif kind == 1848651854 then
		return "首领关卡"
	elseif kind == 1848651855 then
		return "小游戏关卡"
	end
	return GetUnitName(node)
end

function HopeRoute_Description(node)
	local kind = GetUnitTypeId(node)
	if kind == 1848651849 then
		return "常规回合战斗。|n留意敌人意图，和队友|n分配攻击、防御与专注。"
	elseif kind == 1848651850 then
		return "挑战本区域的精英敌人。|n备好补给，确认队伍|n状态后出发。"
	elseif kind == 1848651851 then
		return "购买装备、技能与属性。|n可付费刷新货物，|n注意金币与背包格子。"
	elseif kind == 1848651852 then
		return "随机候选：商店、随机命运、|n泉水、小游戏，或敌人|n可复活的小怪战。|n入场时决定实际结果。"
	elseif kind == 1848651853 then
		return "恢复 30% 最大生命。|n可转职、购买药水，|n整理下一场的补给。"
	elseif kind == 1848651854 then
		return "挑战本区域首领。|n击败首领后进入下一区域。"
	elseif kind == 1848651855 then
		return "随机挑战：射箭、割草、|n躲烈焰、溜冰。入场自动|n聚焦；F3 重新定位角色。"
	end
	return "完成当前奖励与背包整理，再准备出发。"
end

function HopeRoute_UpdateUI()
	local owner = GetPlayerId(GetLocalPlayer())
	local i = 0
	local count = 0
	local slot = 0
	local rows = 0
	local show = HopeRoute_Valid() and HopeRoute_Active(owner) and not HopeRoute_RewardPending(owner)
	local name = ""
	local state = ""
	local x = 0.007
	local y = -0.08
	local width = 0.12
	for _ in _loop_() do
		if i >= 6 then break end
		if HopeRoute_Active(i) then
			count = count + 1
		end
		HopeLayout_Show(HopeLayout_Member[i], false)
		i = i + 1
	end
	rows = count
	if count > 3 then
		rows = _idiv_(count + 1, 2)
		width = 0.058
	end
	HopeLayout_Show(HopeRoute_Panel, show)
	if show then
		HopeLayout_Place(HopeRoute_Panel, 0, 0.014, 0.375, 0.134, 0.086 + 0.012 * I2R(rows))
		HopeLayout_Show(HopeRoute_Text, false)
		HopeLayout_Show(HopeRoute_ReadyButton, not HopeRoute_Ready[owner])
		HopeLayout_Show(HopeRoute_WaitButton, HopeRoute_Ready[owner])
		HopeLayout_Show(HopeRoute_DepartButton, owner == HopeRoute_Leader())
		if HopeRoute_AllReady() then
			DzFrameSetText(HopeRoute_TitleText, "|cffd2b879" .. (HopeRoute_Title(HopeRoute_Node) or "") .. "|r · |cff80ef90已齐|r")
			DzFrameSetText(HopeRoute_DepartButton, "全员已准备 · 出发")
		else
			DzFrameSetText(HopeRoute_TitleText, "|cffd2b879" .. (HopeRoute_Title(HopeRoute_Node) or "") .. "|r")
			DzFrameSetText(HopeRoute_DepartButton, "等待队友 · 出发")
		end
		i = 0
		for _ in _loop_() do
			if i >= 6 then break end
			if HopeRoute_Active(i) then
				if count > 3 then
					name = HopeName_Label(Player(i), 50)
				else
					name = HopeName_Label(Player(i), 70)
				end
				if i == HopeRoute_Leader() then
					name = (name or "") .. "*"
				end
				if HopeRoute_RewardPending(i) then
					state = "|cffffc060…|r"
				elseif udg_hero[i + 1] == nil then
					state = "|cffaaaaaa…|r"
				elseif HopeRoute_Ready[i] then
					state = "|cff80ef90√|r"
				else
					state = "|cffaaaaaa×|r"
				end
				x = 0.007
				y = -0.08 - 0.012 * I2R(slot)
				if count > 3 then
					x = 0.007 + 0.064 * I2R(ModuloInteger(slot, 2))
					y = -0.08 - 0.012 * I2R(_idiv_(slot, 2))
				end
				HopeLayout_Place(HopeLayout_Member[i], HopeRoute_Panel, x, y, width, 0.011)
				if HopeLayout_Member[i] ~= 0 then
					DzFrameSetText(HopeLayout_Member[i], (YDWEGetPlayerColorString(Player(i), name) or "") .. " " .. (state or ""))
				end
				HopeLayout_Show(HopeLayout_Member[i], true)
				slot = slot + 1
			end
			i = i + 1
		end
		if HopeRoute_LastPreview ~= HopeRoute_Node then
			HopeRoute_Details = false
			HopeRoute_LastPreview = HopeRoute_Node
		end
		if HopeRoute_Details then
			DzFrameSetText(HopeRoute_DescriptionText, (HopeRoute_Description(HopeRoute_Node) or "") .. "|n|n完整队伍状态（*为选路玩家）：|n" .. (HopeRoute_Status() or ""))
		end
	end
	HopeLayout_Show(HopeRoute_InfoPanel, show and HopeRoute_Details)
end

function HopeTurn_UpdateUI()
	local p = GetLocalPlayer()
	local i = GetPlayerId(p) + 1
	local j = 0
	local partySize = 0
	local unfinished = 0
	local canEnd = HopeTurn_CanEnd(p)
	local text = ""
	DzFrameShow(HopeTurn_Panel, udg_hero[i] ~= nil and udg_ZhandouZhong and HopeMini_Actor[i] == nil)
	if not udg_ZhandouZhong or HopeMini_Actor[i] ~= nil then
		HopeTurn_IdleTicks = 0
		HopeTurn_Reminded = false
	elseif canEnd then
		for _ in _loop_() do
			if j >= 6 then break end
			if HopeRoute_Active(j) then
				partySize = partySize + 1
				-- Paused teammates are still finishing an action, not already done.
				if IsPlayerInForce(Player(j), udg_WJZ_______weizhunbei) and IsUnitAliveBJ(udg_hero[j + 1]) then
					unfinished = unfinished + 1
				end
			end
			j = j + 1
		end
		if udg_xingdong_dian[i] <= 0 then
			text = "|cffffd060行动点已用完|n请结束回合|r"
		elseif partySize > 1 and unfinished == 1 then
			text = "|cffffd060队友已完成，等待你|n剩余 " .. (I2S(udg_xingdong_dian[i]) or "") .. " 行动点|r"
		else
			text = "|cff80ef90己方第 " .. (I2S(udg_huihe_s) or "") .. " 回合|n剩余 " .. (I2S(udg_xingdong_dian[i]) or "") .. " 行动点|r"
		end
		if HopeTurn_LastRound ~= udg_huihe_s or HopeTurn_LastAP ~= udg_xingdong_dian[i] then
			HopeTurn_IdleTicks = 0
			if HopeTurn_LastRound ~= udg_huihe_s then
				HopeTurn_Reminded = false
			end
		end
		if GetUnitCurrentOrder(udg_hero[i]) == 0 then
			HopeTurn_IdleTicks = HopeTurn_IdleTicks + 1
		else
			HopeTurn_IdleTicks = 0
		end
		if HopeTurn_IdleTicks >= 100 and not HopeTurn_Reminded then
			DisplayTimedTextToPlayer(p, 0, 0, 6.0, "|cffffd060你的回合尚未结束。操作完成后，点击结束回合，或选中英雄按 G。|r")
			HopeTurn_Reminded = true
		end
	else
		HopeTurn_IdleTicks = 0
		if IsUnitAliveBJ(udg_hero[i]) == false then
			text = "角色已倒地|n等待本场结算"
		elseif IsPlayerInForce(p, udg_WJZ_______weizhunbei) and IsUnitPaused(udg_hero[i]) then
			text = "当前动作结算中|n稍后可继续操作"
		elseif HopeTurn_Waiting() > 0 then
			text = "已结束回合|n等待 " .. (I2S(HopeTurn_Waiting()) or "") .. " 位队友"
		else
			text = "|cffffb080敌方行动 / 结算中|n等待下回合|r"
		end
	end
	HopeTurn_LastRound = udg_huihe_s
	HopeTurn_LastAP = udg_xingdong_dian[i]
	DzFrameSetText(HopeTurn_Text, text)
	DzFrameShow(HopeTurn_Button, canEnd)
	if canEnd and udg_xingdong_dian[i] <= 0 then
		DzFrameSetText(HopeTurn_Button, "|cffffd060结束回合 G|r")
	else
		DzFrameSetText(HopeTurn_Button, "|cff80ef90结束回合 G|r")
	end
	p = nil
end

function HopeIntent_UpdateUI()
	local u = HopeIntent_Selected
	local show = udg_ZhandouZhong and not HopeQoL_Expanded and not HopeArchive_Expanded and not HopeGift_Expanded and not HopeRelic_Expanded and HopeMini_Actor[GetPlayerId(GetLocalPlayer()) + 1] == nil and u ~= nil and IsUnitAliveBJ(u) and IsUnitVisible(u, GetLocalPlayer()) and IsUnitSelected(u, GetLocalPlayer())
	local status = ""
	local line = ""
	local lines = 0
	if HopeIntent_Panel == 0 then
		u = nil
		return
	end
	DzFrameShow(HopeIntent_Panel, show)
	if show then
		if HopeIntent_Title ~= 0 then
			if LoadInteger(HopeStatus_History, GetHandleId(u), 4) == 0 then
				DzFrameSetText(HopeIntent_Title, "|cffd2b879" .. (GetUnitName(u) or "") .. " · 下次行动|r")
			else
				DzFrameSetText(HopeIntent_Title, "|cffd2b879" .. (GetUnitName(u) or "") .. " · 当前行动|r")
			end
		end
		if HopeIntent_Text ~= 0 then
			DzFrameSetText(HopeIntent_Text, HopeIntent_Description(u))
		end
		if HopeIntent_Status ~= 0 then
			status = HopeStatus_PoisonDetails(u, GetLocalPlayer())
			if status ~= "" then
				lines = 1
			end
			line = HopeStatus_PoisonPreviewLine(u)
			if line ~= "" then
				if lines > 0 then
					status = (status or "") .. "|n"
				end
				status = (status or "") .. (line or "")
				lines = lines + 1
			end
			line = HopeStatus_PoisonLastLine(u)
			if line ~= "" then
				if lines > 0 then
					status = (status or "") .. "|n"
				end
				status = (status or "") .. (line or "")
				lines = lines + 1
			end
			line = HopeDebuff_Details(u)
			if line ~= "" then
				if lines > 0 then
					status = (status or "") .. "|n"
				end
				status = (status or "") .. (line or "")
				lines = lines + HopeDebuff_Lines(u)
			end
			DzFrameShow(HopeIntent_Status, lines > 0)
			if lines > 0 then
				DzFrameSetText(HopeIntent_Status, status)
				DzFrameSetSize(HopeIntent_Status, 0.208, 0.0128 * I2R(lines))
				DzFrameSetSize(HopeIntent_Panel, 0.224, 0.056 + 0.0128 * I2R(lines))
			else
				DzFrameSetSize(HopeIntent_Panel, 0.224, 0.052)
			end
		end
	end
	u = nil
end

function HopeQoL_BarValue(fill, current, maximum)
	local ratio = 0.0
	if fill == 0 then
		return
	end
	if maximum > 0.0 then
		ratio = RMaxBJ(0.0, RMinBJ(1.0, current / maximum))
	end
	DzFrameShow(fill, ratio > 0.0)
	DzFrameSetSize(fill, 0.12 * RMaxBJ(0.001, ratio), 0.003)
end


function HopeQoL_Label(name, parent, x, y, w, h, value)
	local f = 0
	if parent == 0 then
		return 0
	end
	f = DzCreateFrameByTagName("TEXT", name, parent, "HopePassText", 0)
	if f == 0 then
		return 0
	end
	-- No template-only creation: text remains independent of a loaded blueprint.
	DzFrameSetPoint(f, 0, parent, 0, x, y)
	DzFrameSetSize(f, w, h)
	DzFrameSetFont(f, "Fonts\\ZiTi.ttf", 0.0095, 0)
	DzFrameSetText(f, value)
	DzFrameShow(f, true)
	return f
end

-- The passive text child keeps the entire flat button clickable.




-- Decorative lines never receive a click handler. Anchor both ends so a party
-- size change resizes the border with its panel rather than stretching a bitmap.
function HopeQoL_Edge(name, parent, first, second, horizontal)
	local f = DzCreateFrameByTagName("BACKDROP", name, parent, "HopePassBackdrop", 0)
	if f == 0 then
		return
	end
	DzFrameSetTexture(f, "HopeUI\\focus-fill.blp", 0)
	DzFrameSetAlpha(f, 115)
	DzFrameSetPoint(f, first, parent, first, 0.0, 0.0)
	DzFrameSetPoint(f, second, parent, second, 0.0, 0.0)
	if horizontal then
		DzFrameSetSize(f, 0.0, 0.00055)
	else
		DzFrameSetSize(f, 0.00055, 0.0)
	end
end

-- Fade only the background sibling, keeping text and controls fully opaque.
function HopeQoL_Surface(name, x, y, w, h)
	local parent = 0
	local background = 0
	-- Critical parents must not depend on DzLoadToc or blueprint lookup success.
	parent = DzCreateFrameByTagName("FRAME", name, DzGetGameUI(), "HopePassFrame", 0)
	if parent == 0 then
		return 0
	end
	background = DzCreateFrameByTagName("BACKDROP", (name or "") .. "Background", parent, "HopePassBackdrop", 0)
	DzFrameSetAbsolutePoint(parent, 0, x, y)
	DzFrameSetSize(parent, w, h)
	if background ~= 0 then
		DzFrameSetAllPoints(background, parent)
		-- This exact built-in texture is used by the reference map's actual console.
		-- Avoid the old custom JPEG's YCbCr/BGRA color interpretation entirely.
		DzFrameSetTexture(background, "Textures\\Black32.blp", 0)
		DzFrameSetAlpha(background, 220)
		DzFrameShow(background, true)
	end
	HopeQoL_Edge((name or "") .. "Top", parent, 0, 2, true)
	HopeQoL_Edge((name or "") .. "Bottom", parent, 6, 8, true)
	HopeQoL_Edge((name or "") .. "Left", parent, 0, 6, false)
	HopeQoL_Edge((name or "") .. "Right", parent, 2, 8, false)
	-- A partially constructed UI must never leave an empty blocker over the map.
	-- The state refresh shows each completed panel only when it is needed.
	DzFrameShow(parent, false)
	return parent
end

function HopeQoL_Fill(name, parent, x, y, texture)
	local track = 0
	local fill = 0
	if parent == 0 then
		return 0
	end
	track = DzCreateFrameByTagName("BACKDROP", (name or "") .. "Track", parent, "HopePassBackdrop", 0)
	fill = DzCreateFrameByTagName("BACKDROP", name, parent, "HopePassBackdrop", 0)
	if track ~= 0 then
		DzFrameSetPoint(track, 0, parent, 0, x, y)
		DzFrameSetSize(track, 0.12, 0.003)
		DzFrameSetTexture(track, "HopeUI\\bar-track.blp", 0)
	end
	if fill ~= 0 then
		DzFrameSetPoint(fill, 0, parent, 0, x, y)
		DzFrameSetSize(fill, 0.12, 0.003)
		DzFrameSetTexture(fill, texture, 0)
	end
	return fill
end

function HopeQoL_Bind(frame, action, sync)
	if frame ~= 0 then
		DzFrameSetScriptByCode(frame, 1, action, sync)
	end
end

