	if DzGetTriggerUIEventPlayer() == GetLocalPlayer() then
		HopeChoice_Hidden = true
		if HopeGrowth_Panel ~= 0 then
			DzFrameShow(HopeGrowth_Panel, false)
		end
		HopeChoice_ApplyVisibility()
	end
end

function HopeGrowth_Refresh()
	local owner = GetPlayerId(GetLocalPlayer())
	local i = owner + 1
	local show = false
	local status = ""
	if not HopeGrowth_UIReady or owner < 0 or owner >= 6 then
		return
	end
	show = HopeGrowth_Pending[owner] and not HopeChoice_Hidden and not HopeRoute_Assigning
	DzFrameShow(HopeGrowth_Panel, show)
	if not show then
		return
	end
	-- Resuming with F6 returns to this choice and closes any intervening panels.
	HopeQoL_Expanded = false
	HopeArchive_Expanded = false
	HopeGift_Expanded = false
	HopeRelic_Expanded = false
	HopeRoute_Details = false
	HopeJob_Expanded = false
	DzFrameSetText(HopeGrowth_Summary, "存档积分  " .. (I2S(udg_Wj_jf[i]) or "") .. "    免费重置  " .. (I2S(udg_CZ_czcs[i]) or "") .. " 次")
	DzFrameSetText(HopeGrowth_ValueText[0], "力量  +" .. (HopeQoL_GradedGrowth(udg_cz1Str_up[i], false) or ""))
	DzFrameSetText(HopeGrowth_ValueText[1], "敏捷  +" .. (HopeQoL_GradedGrowth(udg_cz2Agi_up[i], false) or ""))
	DzFrameSetText(HopeGrowth_ValueText[2], "智力  +" .. (HopeQoL_GradedGrowth(udg_cz3Int_up[i], false) or ""))
	DzFrameSetText(HopeGrowth_ValueText[3], "生命  +" .. (HopeQoL_GradedGrowth(udg_cz4Hp_up[i], true) or ""))
	DzFrameSetText(HopeGrowth_ValueText[4], "魔力  +" .. (HopeQoL_GradedGrowth(udg_cz5Mp_up[i], false) or ""))
	DzFrameSetText(HopeGrowth_ValueText[5], "专注  +" .. (HopeQoL_GradedGrowth(udg_cz6Dex_up[i], false) or ""))
	DzFrameSetText(HopeGrowth_FreeButton, "免费重置 · 剩余" .. (I2S(udg_CZ_czcs[i]) or "") .. "次")
	status = "每次重置全部六项成长；免费与积分次数独立。"
	if not HopeCloud_CanWrite(GetLocalPlayer()) then
		status = "存档积分暂不可用；仍可免费重置或确认成长。"
	elseif udg_Wj_jf[i] < 5 - IMinBJ(3, HopeMeta_Tal(i - 1, 12)) then
		status = "额外重置需要" .. (I2S(5 - IMinBJ(3, HopeMeta_Tal(i - 1, 12))) or "") .. "积分，当前不足。"
	end
	DzFrameSetText(HopeGrowth_Footer, (status or "") .. "|n确认后，本局不能再次重置初始成长。")
	DzFrameSetText(HopeGrowth_PaidButton, "积分重置 · " .. (I2S(5 - IMinBJ(3, HopeMeta_Tal(i - 1, 12))) or "") .. "积分")
end

function HopeGrowth_CreateUI()
	local f = 0
	local index = 0
	local x = 0.014
	local y = -0.074
	DestroyTimer(GetExpiredTimer())
	HopeGrowth_Panel = HopeQoL_Surface("HopeGrowthPanel", 0.229, 0.535, 0.342, 0.323)
	if HopeGrowth_Panel == 0 then
		return
	end
	HopeGrowth_Title = HopeQoL_Label("HopeGrowthTitle", HopeGrowth_Panel, 0.014, -0.01, 0.21, 0.021, "|cffffd060初始成长|r")
	f = HopeQoL_Button("HopeGrowthFold", HopeGrowth_Panel, 0.252, -0.006, 0.076, 0.026, "收起 F6")
	HopeQoL_Bind(f, HopeGrowth_Fold, false)
	HopeGrowth_Summary = HopeQoL_Label("HopeGrowthSummary", HopeGrowth_Panel, 0.014, -0.041, 0.314, 0.02, "")
	HopeGrowth_UIReady = HopeGrowth_Title ~= 0 and HopeGrowth_Summary ~= 0 and f ~= 0
	for _ in _loop_() do
		if index >= 6 then break end
		if index >= 3 then
			x = 0.178
			y = -0.074 - I2R(index - 3) * 0.03
		else
			x = 0.014
			y = -0.074 - I2R(index) * 0.03
		end
		HopeGrowth_ValueText[index] = HopeQoL_Label("HopeGrowthValue" .. (I2S(index) or ""), HopeGrowth_Panel, x, y, 0.15, 0.022, "")
		HopeGrowth_UIReady = HopeGrowth_UIReady and HopeGrowth_ValueText[index] ~= 0
		index = index + 1
	end
	f = HopeQoL_Label("HopeGrowthExplanation", HopeGrowth_Panel, 0.014, -0.167, 0.314, 0.044, "以上为每级成长值；三围小数会累积。|n魔力提升技能伤害，专注提升精确打击伤害。|n额外重置每次基础5积分，资源天赋可降至2积分。")
	HopeGrowth_FreeButton = HopeQoL_Button("HopeGrowthFree", HopeGrowth_Panel, 0.014, -0.218, 0.151, 0.028, "")
	HopeGrowth_PaidButton = HopeQoL_Button("HopeGrowthPaid", HopeGrowth_Panel, 0.177, -0.218, 0.151, 0.028, "积分重置 · 5积分")
	HopeGrowth_AcceptButton = HopeQoL_Button("HopeGrowthAccept", HopeGrowth_Panel, 0.014, -0.253, 0.314, 0.028, "以当前成长开始游戏")
	HopeQoL_Bind(HopeGrowth_FreeButton, HopeGrowth_FreeClick, true)
	HopeQoL_Bind(HopeGrowth_PaidButton, HopeGrowth_PaidClick, true)
	HopeQoL_Bind(HopeGrowth_AcceptButton, HopeGrowth_AcceptClick, true)
	HopeGrowth_Footer = HopeQoL_Label("HopeGrowthFooter", HopeGrowth_Panel, 0.014, -0.288, 0.314, 0.03, "")
	HopeGrowth_UIReady = HopeGrowth_UIReady and f ~= 0 and HopeGrowth_FreeButton ~= 0 and HopeGrowth_PaidButton ~= 0 and HopeGrowth_AcceptButton ~= 0 and HopeGrowth_Footer ~= 0
	DzFrameShow(HopeGrowth_Panel, false)
end

function HopeEvent_Refresh()
	local text = ""
	local j = 0
	if HopeEvent_Panel == 0 then
		return
	end
	if HopeEvent_Seen ~= HopeEvent_Sequence then
		HopeEvent_Seen = HopeEvent_Sequence
		HopeEvent_Offset = HopeEvent_Start
		HopeEvent_Open = true
		HopeLayout_Focus(14)
	end
	j = IMaxBJ(IMaxBJ(0, HopeEvent_Count - 512), HopeEvent_Offset)
	for _ in _loop_() do
		if j >= HopeEvent_Count or j >= HopeEvent_Offset + 13 then break end
		if text ~= "" then
			text = (text or "") .. "|n"
		end
		text = (text or "") .. (HopeEvent_Line[ModuloInteger(j, 512)] or "")
		j = j + 1
	end
	DzFrameSetText(HopeEvent_Body, text)
	DzFrameSetText(HopeEvent_Status, "各自关闭 · " .. (I2S(HopeEvent_Offset + 1) or "") .. "-" .. (I2S(j) or "") .. "/" .. (I2S(HopeEvent_Count) or "") .. "行")
end
function HopeLayout_Mode()
	local owner = GetPlayerId(GetLocalPlayer())
	local i = 1
	if HopeMeta_Open then
		return 15
	end
	if HopeMarket_Open then
		return 16
	end
	if HopeRoute_Assigning then
		return 10
	end
	if not HopeChoice_Hidden then
		if HopeGrowth_Pending[owner] then
			return 11
		end
		if HopeChoice_LootPending() then
			return 12
		end
		for _ in _loop_() do
			if i > HopeChoice_DialogCount then break end
			if HopeChoice_DialogPending[i] and HopeChoice_Owner[i] == owner then
				return 13
			end
			i = i + 1
		end
	end
	if HopeEvent_Open then
		return 14
	end
	if HopeQoL_Expanded then
		return 1
	elseif HopeArchive_Expanded then
		return 2
	elseif HopeGift_Expanded then
		return 3
	elseif HopeRelic_Expanded then
		return 4
	elseif HopeJob_Expanded then
		return 5
	elseif HopeRoute_PickerOpen and not udg_ZhandouZhong and HopeRoute_AvailableCount > 0 then
		return 6
	elseif HopeDraw_Open then
		return 7
	elseif HopeRoute_Details and HopeRoute_Valid() then
		return 9
	end
	return 0
end
function HopeLayout_Apply()
	local mode = 0
	local owner = GetPlayerId(GetLocalPlayer())
	local i = 1
	local newest = 0
	local active = owner >= 0 and owner < 6 and udg_hero[owner + 1] ~= nil
	local dock = active and mode < 10
	HopeEvent_Refresh()
	mode = HopeLayout_Mode()
	dock = active and mode < 10
	HopeLayout_Show(HopeEvent_Panel, mode == 14)
	HopeLayout_Show(HopeEvent_Button, dock and HopeEvent_Count > 0)
	HopeLayout_Show(HopeQoL_StatsButton, dock)
	HopeLayout_Show(HopeLayout_Save, dock)
	HopeLayout_Show(HopeLayout_Relic, dock)
	HopeLayout_Show(HopeGift_OpenButton, dock)
	HopeLayout_Show(HopeLayout_History, dock)
	HopeLayout_Show(HopeLayout_Route, dock and not udg_ZhandouZhong)
	HopeLayout_Show(HopeQoL_Panel, mode == 1 and active)
	HopeLayout_Show(HopeArchive_Panel, mode == 2 and HopeArchive_UIReady)
	HopeLayout_Show(HopeGift_Panel, mode == 3 and HopeGift_UIReady)
	HopeLayout_Show(HopeRelic_Panel, mode == 4 and HopeRelic_UIReady)
	HopeLayout_Show(HopeJob_Panel, mode == 5)
	HopeLayout_Show(HopeRoute_Picker, mode == 6)
	HopeLayout_Show(HopeDraw_Panel, mode == 7)
	HopeLayout_Show(HopeRoute_InfoPanel, mode == 9)
	HopeLayout_Show(HopeRoute_AssignPanel, mode == 10 and owner == HopeRoute_Host())
	HopeLayout_Show(HopeGrowth_Panel, mode == 11 and HopeGrowth_UIReady)
	HopeLayout_Show(udg_UI_sg[1], mode == 12)
	for _ in _loop_() do
		if i > HopeChoice_DialogCount then break end
		if HopeChoice_DialogPending[i] and HopeChoice_Owner[i] == owner then
			newest = i
		end
		i = i + 1
	end
	i = 1
	for _ in _loop_() do
		if i > 13 then break end
		HopeLayout_Show(HopeModern_Panel[i], mode == 13 and i == newest)
		i = i + 1
	end
	-- Passive readouts yield to overlays, rather than covering their content.
	HopeLayout_Show(HopeDamage_Panel, mode == 0 and active)
	if mode ~= 0 then
		HopeLayout_Show(HopeIntent_Panel, false)
		HopeLayout_Show(HopeTurn_Panel, false)
		HopeLayout_Show(HopeJob_OpenButton, false)
	end
end

function HopeThird_Resource(u, p)
	local kind = GetUnitTypeId(u)
	local token = HopeChallenge_TurnToken()
	local level = HopeThird_Level(u)
	local count = 0
	local limit = 2
	local mask = 0
	if level <= 0 then
		return ""
	end
	if kind == 1211117636 then
		if HopeThird_Cavalry[p] then
			return "|cff80ef90骑势就绪 · 下次强化|r"
		end
		return "|cffaaaaaa骑势 · 冲锋后蓄势|r"
	elseif kind == 1311781176 then
		if level == 1 then
			limit = 3
		end
		if HopeThird_ComboToken[p] == token then
			if HopeThird_ComboPaid[p] then
				return "|cff80ef90连势 · 本回合已回点|r"
			end
			count = IMinBJ(limit, HopeThird_ComboCount[p])
		end
		return "|cffd2b879连势 " .. (I2S(count) or "") .. "/" .. (I2S(limit) or "") .. " · 满后回点|r"
	elseif kind == 1211117620 then
		if HopeThird_PressureToken[p] == token then
			count = HopeThird_Pressure[p]
		end
		return "|cffd2b879压制 " .. (I2S(count) or "") .. "/3 · 换目标重置|r"
	elseif kind == 1311781189 then
		if HopeThird_FireTarget[p] ~= nil and GetWidgetLife(HopeThird_FireTarget[p]) > 0.405 then
			count = HopeThird_Get(GetHandleId(HopeThird_FireTarget[p]), p)
		end
		return "|cfffe8a0e最近目标火种 " .. (I2S(count) or "") .. "/3|r"
	elseif kind == 1328558134 then
		if HopeThird_HitsToken[p] == token then
			count = HopeThird_Hits[p]
			if HopeThird_HealCount[p] >= 2 then
				return "|cff80ef90连环 · 本回合已回复2次|r"
			end
		end
		return "|cff68b99a连环 " .. (I2S(count) or "") .. "/3 · 满后回复|r"
	elseif kind == 1213870131 then
		if HopeThird_HiddenToken[p] == token then
			mask = HopeThird_HiddenMask[p]
		end
		if mask >= 8 then
			return "|cff80ef90三律 · 本回合已贯通|r"
		end
		if ModuloInteger(mask, 2) == 1 then
			count = count + 1
		end
		if ModuloInteger(mask, 4) >= 2 then
			count = count + 1
		end
		if mask >= 4 then
			count = count + 1
		end
		return "|cff76cdd0三律 " .. (I2S(count) or "") .. "/2 · Q D V任选两式|r"
	end
	return ""
end

function HopeProfession_Text(u, p)
	local kind = 0
	local current = 0
	local capacity = 0
	if p < 1 or p > 6 or u == nil then
		return ""
	end
	if HopeMini_Actor[p] ~= nil then
		return ""
	end
	kind = GetUnitTypeId(u)
	if kind == 1211117637 then
		current = LoadInteger(YDHT, GetHandleId(u), 812780749)
		capacity = GetUnitAbilityLevel(u, 1093678161) + 1
		if current <= 0 then
			return "|cffff8585子弹 " .. (I2S(current) or "") .. "/" .. (I2S(capacity) or "") .. " · Q装填|r"
		end
		return "|cffd2b879子弹 " .. (I2S(current) or "") .. "/" .. (I2S(capacity) or "") .. "|r"
	elseif kind == 1311781191 then
		current = HopeMonk_Qi[p]
		if current >= 3 then
			return "|cff80ef90气 " .. (I2S(current) or "") .. "/3 · 已满|r"
		end
		return "|cff76cdd0气 " .. (I2S(current) or "") .. "/3|r"
	elseif kind == 1311781185 and GetUnitAbilityLevel(u, 1093677901) > 1 then
		-- The live passive starts at rank 2 and awards STR on the 15th heavy chop.
		current = udg_Zhongkan_cs[p]
		if current >= 14 then
			return "|cff80ef90重砍 " .. (I2S(current) or "") .. "/15 · 下次+1力|r"
		end
		return "|cffd2b879重砍 " .. (I2S(current) or "") .. "/15|r"
	end
	return HopeThird_Resource(u, p)
end

function HopeQoL_RefreshContent()
	local p = GetPlayerId(GetLocalPlayer()) + 1
	local u = udg_hero[p]
	local armor = 0.0
	local lo = 0
	local hi = 0
	local focus = ""
	local detail = ""
	local reduction = ""
	local active = u ~= nil and p <= 6
	local picking = HopeChoice_HasPending() and not HopeChoice_Hidden
	local actor = u
	HopeQoL_RefreshLegacyAP()
	HopeTeam_UpdateAP()
	HopeIntent_RefreshAll()
	HopeSkill_Refresh()
	HopeChoice_Refresh()
	HopeGrowth_Refresh()
	HopeArchive_Refresh()
	HopeGift_Refresh()
	HopeRelic_Refresh()
	if not HopeQoL_UIReady then
		u = nil
		actor = nil
		return
	end
	HopeRoute_UpdateUI()
	HopeTurn_UpdateUI()
	HopeIntent_UpdateUI()
	-- The leftmost reward card overlaps this corner. Temporarily yield to the original choice UI.
	DzFrameShow(HopeQoL_Hud, active and HopeQoL_Visible and not picking)
	DzFrameShow(HopeQoL_Restore, active and not HopeQoL_Visible and not picking)
	DzFrameShow(HopeQoL_Panel, active and HopeQoL_Expanded and not HopeArchive_Expanded and not HopeGift_Expanded and not HopeRelic_Expanded and not picking)
	DzFrameShow(HopeQoL_StatsButton, active and not picking)
	DzFrameShow(HopeGift_OpenButton, active and not picking)
	if active then
		if LoadBoolean(YDHT, GetHandleId(u), 149034428) then
			focus = "|cffffd060精确打击就绪|r"
		elseif udg_zhuanzhuzhi_sy[p] >= 3.0 then
			focus = "|cff80ef90F 启用专注|r"
		else
			focus = "|cffaaaaaa专注不足 3|r"
		end
		DzFrameSetText(HopeQoL_Resources, "|cffd2b879行动 " .. (I2S(udg_xingdong_dian[p]) or "") .. "/" .. (I2S(udg_xingdong_dianSx[p]) or "") .. "|r  专注 " .. (HopeQoL_CompactNumber(udg_zhuanzhuzhi_sy[p]) or "") .. "/" .. (HopeQoL_CompactNumber(udg_DEX[p]) or ""))
		detail = HopeProfession_Text(u, p)
		if detail ~= "" then
			focus = detail
		end
		DzFrameSetText(HopeQoL_Status, (focus or "") .. "|n|cffaaaaaa背包 " .. (I2S(HopeQoL_Slots(u)) or "") .. "/6 · 助手 " .. (I2S(HopeQoL_Slots(udg_Bei_bao_danwei[p])) or "") .. "/6|r")
		if HopeMini_Actor[p] ~= nil then
			actor = HopeMini_Actor[p]
			DzFrameSetText(HopeQoL_Resources, "|cffd2b879小游戏角色|r")
			DzFrameSetText(HopeQoL_Status, "F3 重新定位小游戏角色|n剩余时间见游戏计时器")
		end
		DzFrameSetText(HopeQoL_LifeText, "|cff68b99a生命 " .. (I2S(R2I(GetUnitState(actor, UNIT_STATE_LIFE))) or "") .. "/" .. (I2S(R2I(GetUnitState(actor, UNIT_STATE_MAX_LIFE))) or "") .. "|r")
		DzFrameSetText(HopeQoL_ManaText, "|cff76a7d0魔法 " .. (I2S(R2I(GetUnitState(actor, UNIT_STATE_MANA))) or "") .. "/" .. (I2S(R2I(GetUnitState(actor, UNIT_STATE_MAX_MANA))) or "") .. "|r")
		HopeQoL_BarValue(HopeQoL_LifeFill, GetUnitState(actor, UNIT_STATE_LIFE), GetUnitState(actor, UNIT_STATE_MAX_LIFE))
		HopeQoL_BarValue(HopeQoL_ManaFill, GetUnitState(actor, UNIT_STATE_MANA), GetUnitState(actor, UNIT_STATE_MAX_MANA))
		if HopeQoL_Expanded then
			armor = GetUnitState(u, ConvertUnitState(32))
			if armor >= 0.0 then
				reduction = "护甲减伤 " .. (HopeQoL_Number(100.0 * (0.04 * armor) / (1.0 + 0.04 * armor)) or "") .. "%"
			else
				reduction = "负护甲：承受额外物理伤害"
			end
			hi = 120 + GetHeroStr(u, true)
			lo = IMinBJ(hi, 90 + _idiv_(GetHeroAgi(u, true), 2))
			detail = "|cffd2b879战斗属性|r|n"
			detail = (detail or "") .. "攻击基值  " .. (HopeQoL_Number(GetUnitState(u, ConvertUnitState(20))) or "") .. "|n平砍浮动  " .. (I2S(lo) or "") .. "-" .. (I2S(hi) or "") .. "%|n"
			detail = (detail or "") .. "护甲  " .. (HopeQoL_Number(armor) or "") .. "|n" .. (reduction or "") .. "|n"
			detail = (detail or "") .. "暴击率  " .. (I2S(udg_Baoji_Lv[p]) or "") .. "%|n暴击伤害  " .. (HopeQoL_Number(100.0 * udg_Baoji_Damage[p]) or "") .. "%|n"
			detail = (detail or "") .. "法术 / 技能  " .. (HopeQoL_Number(100.0 * udg_Fashang_Dm[p]) or "") .. "% / " .. (HopeQoL_Number(100.0 * udg_Skill_Dm[p]) or "") .. "%|n"
			detail = (detail or "") .. "精确打击  " .. (HopeQoL_Number(100.0 * udg_jingque_Daji_jiacheng[p]) or "") .. "%|n最终伤害  " .. (HopeQoL_Number(100.0 * udg_Zuizhong_Dm[p]) or "") .. "%|n"
			detail = (detail or "") .. "回合结束加甲  " .. (HopeQoL_Number(udg_Defend_HUIHE[p]) or "") .. "|n防御动作额外护甲  " .. (HopeQoL_Number(udg_Defend_fangyu[p]) or "")
			DzFrameSetText(HopeQoL_Details, detail)
			detail = "|cffd2b879基础属性 · Lv." .. (I2S(GetHeroLevel(u)) or "") .. "|r|n"
			detail = (detail or "") .. "力量 " .. (I2S(GetHeroStr(u, true)) or "") .. "  敏捷 " .. (I2S(GetHeroAgi(u, true)) or "") .. "  智力 " .. (I2S(GetHeroInt(u, true)) or "") .. "|n"
			detail = (detail or "") .. "三围总和  " .. (I2S(GetHeroStr(u, true) + GetHeroAgi(u, true) + GetHeroInt(u, true)) or "") .. "|n专注上限  " .. (HopeQoL_Number(udg_DEX[p]) or "") .. "|n|n"
			detail = (detail or "") .. "|cffd2b879每级成长|r|n力量  +" .. (HopeQoL_GradedGrowth(udg_cz1Str_up[p], false) or "") .. "|n敏捷  +" .. (HopeQoL_GradedGrowth(udg_cz2Agi_up[p], false) or "") .. "|n智力  +" .. (HopeQoL_GradedGrowth(udg_cz3Int_up[p], false) or "") .. "|n"
			detail = (detail or "") .. "生命  +" .. (HopeQoL_GradedGrowth(udg_cz4Hp_up[p], true) or "") .. "|n魔力  +" .. (HopeQoL_GradedGrowth(udg_cz5Mp_up[p], false) or "") .. "|n专注  +" .. (HopeQoL_GradedGrowth(udg_cz6Dex_up[p], false) or "")
			DzFrameSetText(HopeQoL_GrowthDetails, detail)
		end
	end
	u = nil
	actor = nil
end
function HopeQoL_Refresh()
	HopeQoL_RefreshContent()
	HopeLayout_Apply()
end

-- Resource loading is an isolated timer thread. If it aborts, the independent
-- construction timer can still build generic containers, text and fallback buttons.
function HopeQoL_LoadUIResources()
	DestroyTimer(GetExpiredTimer())
	HopeQoL_UIResources = "加载中"
	DzLoadToc("HopeUI\\modern-ui.toc")
	HopeQoL_UIResources = "加载调用已返回"
end

-- Only UI allocations occur here, after blocking map initialization is over.
function HopeQoL_CreateUI()
	local f = 0
	DestroyTimer(GetExpiredTimer())
	HopeQoL_UIPhase = "创建基础容器"
	HopeQoL_Hud = HopeQoL_Surface("HopeQoLHud", 0.014, 0.5, 0.134, 0.117)
	if HopeQoL_Hud == 0 then
		DisplayTimedTextToPlayer(GetLocalPlayer(), 0, 0, 15.0, "基础界面创建失败；输入 -ui 查看状态。原生技能、装备及快捷操作保留。")
