	f = HopeQoL_Label("HopeQoLRules", HopeQoL_Panel, 0.009, -0.192, 0.322, 0.087, "|cffd2b879属性与成长如何生效|r|n力量：每点 +2 生命、平砍浮动上限 +1%。|n敏捷：每两点 +1 攻击、浮动下限 +1%。|n智力：每点 +1 魔法，每三点 +1% 法伤。|n生命成长直接加生命；主属性每点另加 0.5 攻击。|n魔力 / 专注成长：每级增加成长值 ÷ 2 个百分点的|n技能 / 精确打击伤害。小数累积；特殊技能按其浮动。")
	DzFrameShow(HopeQoL_Panel, false)
	-- A real, discoverable details action is separate from the F4 keyboard legend.
	HopeQoL_StatsButton = HopeQoL_Button("HopeStatsOpen", DzGetGameUI(), 0, 0, 0.115, 0.023, "属性详情")
	DzFrameClearAllPoints(HopeQoL_StatsButton)
	DzFrameSetAbsolutePoint(HopeQoL_StatsButton, 0, 0.025, 0.238)
	HopeQoL_Bind(HopeQoL_StatsButton, HopeQoL_ToggleStats, false)
	DzFrameShow(HopeQoL_StatsButton, false)
	HopeGift_OpenButton = HopeQoL_Button("HopeGiftOpen", DzGetGameUI(), 0, 0, 0.035, 0.024, "抽奖")
	if HopeGift_OpenButton ~= 0 then
		DzFrameClearAllPoints(HopeGift_OpenButton)
		DzFrameSetAbsolutePoint(HopeGift_OpenButton, 0, 0.105, 0.208)
		HopeQoL_Bind(HopeGift_OpenButton, HopeGift_Toggle, false)
		DzFrameShow(HopeGift_OpenButton, false)
	end
	DzFrameShow(HopeQoL_Hud, false)
	-- A compact target readout grows only for effects present on the selected enemy.
	-- It has no click controls and disappears when that enemy is no longer selected.
	HopeIntent_Title = HopeQoL_Label("HopeIntentTitle", HopeIntent_Panel, 0.008, -0.005, 0.208, 0.014, "")
	HopeIntent_Text = HopeQoL_Label("HopeIntentText", HopeIntent_Panel, 0.008, -0.021, 0.208, 0.025, "")
	HopeIntent_Status = HopeQoL_Label("HopeIntentStatus", HopeIntent_Panel, 0.008, -0.05, 0.208, 0.014, "")
	if HopeIntent_Status ~= 0 then
		DzFrameShow(HopeIntent_Status, false)
	end
	DzFrameShow(HopeIntent_Panel, false)
	HopeChoice_Button = HopeQoL_Button("HopeChoiceToggle", DzGetGameUI(), 0, 0, 0.102, 0.026, "暂时收起选择")
	if HopeChoice_Button ~= 0 then
		DzFrameClearAllPoints(HopeChoice_Button)
		DzFrameSetAbsolutePoint(HopeChoice_Button, 0, 0.165, 0.557)
		HopeQoL_Bind(HopeChoice_Button, HopeChoice_Toggle, false)
		DzFrameShow(HopeChoice_Button, false)
	end
	HopeArchive_CreateUI()
	HopeGift_CreateUI()
	HopeRelic_CreateUI()
	HopeQoL_UIReady = HopeQoL_Hud ~= 0 and HopeRoute_Panel ~= 0 and HopeTurn_Panel ~= 0 and HopeQoL_Panel ~= 0 and HopeQoL_LifeText ~= 0 and HopeQoL_Details ~= 0 and HopeQoL_GrowthDetails ~= 0
	if HopeQoL_UIReady then
		HopeQoL_UIPhase = "已完成"
	else
		HopeQoL_UIPhase = "基础控件缺失"
	end
end

function HopeQoL_Diagnostics()
	if GetTriggerPlayer() == GetLocalPlayer() then
		DisplayTimedTextToPlayer(GetLocalPlayer(), 0, 0, 20.0, "AI爬塔 1.0.4：" .. (HopeQoL_UIPhase or "") .. "；按钮回退 " .. (I2S(HopeQoL_UIFallbacks) or "") .. "|n资源：" .. (HopeQoL_UIResources or "") .. "|n速览 " .. (I2S(HopeQoL_Hud) or "") .. " / 准备 " .. (I2S(HopeRoute_Panel) or "") .. " / 属性 " .. (I2S(HopeQoL_Panel) or "") .. " / 回合 " .. (I2S(HopeTurn_Panel) or "") .. "|n文字：生命 " .. (I2S(HopeQoL_LifeText) or "") .. " / 属性 " .. (I2S(HopeQoL_Details) or ""))
	end
end

-- Allocate synchronized gameplay handles before any optional UI construction.
-- A template failure must not remove chat, keys, tags or the refresh timer.
function HopeQoL_Init()
	local i = 0
	local chat = CreateTrigger()
	local leave = CreateTrigger()
	local diagnostic = CreateTrigger()
	local q = CreateQuest()
	for _ in _loop_() do
		if i >= 6 then break end
		TriggerRegisterPlayerChatEvent(chat, Player(i), "-ready", true)
		TriggerRegisterPlayerChatEvent(chat, Player(i), "-wait", true)
		TriggerRegisterPlayerChatEvent(chat, Player(i), "-route", true)
		TriggerRegisterPlayerChatEvent(diagnostic, Player(i), "-ui", true)
		TriggerRegisterPlayerEvent(leave, Player(i), EVENT_PLAYER_LEAVE)
		i = i + 1
	end
	TriggerAddAction(chat, HopeRoute_Chat)
	TriggerAddAction(leave, HopeRoute_Leave)
	TriggerAddAction(diagnostic, HopeQoL_Diagnostics)
	DzTriggerRegisterKeyEventByCode(nil, 113, 1, false, HopeQoL_SelectBag)
	DzTriggerRegisterKeyEventByCode(nil, 114, 1, false, HopeQoL_SelectHero)
	DzTriggerRegisterKeyEventByCode(nil, 115, 1, false, HopeQoL_ToggleStats)
	DzTriggerRegisterKeyEventByCode(nil, 116, 1, false, HopeQoL_ToggleHud)
	DzTriggerRegisterKeyEventByCode(nil, 117, 1, false, HopeChoice_ToggleLocal)
	i = 1
	for _ in _loop_() do
		if i > 6 then break end
		HopeTeam_APTag[i] = CreateTextTag()
		DzTextTagSetShadowColor(HopeTeam_APTag[i], 0)
		SetTextTagPermanent(HopeTeam_APTag[i], true)
		SetTextTagVisibility(HopeTeam_APTag[i], false)
		i = i + 1
	end
	QuestSetTitle(q, "AI爬塔 1.0.4 · 快捷指南")
	QuestSetDescription(q, "速览位于左上头像下，显示生命、魔法、行动点、专注与背包占用。|nF2：定位助手。F3：定位英雄或小游戏角色，保留缩放。|nF4：展开/收起属性。Esc：只关闭已展开的资料面板，不打开属性。|nF5：只收起速览，再按恢复；准备、队友行动点、怪物意图和结束回合仍显示。|nF6：收起/展开战利品、成长、升级与技能替换，保留选项。收起后即可查看其他数据。" .. "|nQ 攻击、W 防御、F 专注、G 结束回合、H 药剂、R 镜头锁定、Tab 查看保留。|n右键双击物品可在英雄和助手之间转交；失败时检查格子。防御可重复使用，需足够行动点与魔法。|n小地图上方可直接查看属性、存档、遗物和抽奖；这些入口不受 F5 影响。")
	QuestSetIconPath(q, "ReplaceableTextures\\CommandButtons\\BTNSelectHeroOn.blp")
	QuestSetRequired(q, false)
	QuestSetDiscovered(q, true)
	q = CreateQuest()
	QuestSetTitle(q, "AI爬塔 1.0.4 · 属性与存档")
	QuestSetDescription(q, "点击属性详情或按 F4，查看三围、六项成长与评级、暴击、护甲减伤和伤害倍率。Esc 只关闭已打开的属性或存档面板，也可关闭遗物和礼包抽奖。|n存档显示十项永久成长的累计加成、次数、上限与兑换价格。每项最多 5 次；新购成长在平台结算后于下一局生效。|n生命 +10、魔法 +1 是免费基底，不计入购买。永久数据未载入时暂不能兑换。" .. "|n遗物独立显示本局收藏，点击名称查看完整效果，底部翻页。|n礼包抽奖每次5积分，55%谢谢惠顾；六种礼包概率在面板公开。重复结果不叠加、不重抽、不返还，全部拥有后停止抽奖。新礼包永久解锁，提交平台结算后下局生效。|n奖励挡住数据时，点收起或按 F6，再原样展开继续选择。|n选中敌人可看简短行动预告；切回角色后自动收起。")
	QuestSetRequired(q, false)
	QuestSetDiscovered(q, true)
	q = CreateQuest()
	QuestSetTitle(q, "选路、准备与出发")
	QuestSetDescription(q, "开局由主机指定路线选择者。路线选择者点击黄色可达节点或路线列表提出路线，路线选择者选路时自动准备（仍须先领完奖励），其他人完成战利品、购物和背包整理后点击准备。全员准备后，路线选择者点击准备面板的【出发】。|n未选择战利品（或明确放弃）时不能准备；新发放奖励会撤销准备。|n换路线会自动确认路线选择者，队友需重新确认；取消准备立即阻止推进。离开玩家不计入等待人数，其他人重新确认。|n聊天命令：-ready 准备；-wait 取消；-route 查看状态。准备面板独立显示，F5 只收起速览。|n没有超时自动出发或强制跳过队友。")
	QuestSetRequired(q, false)
	QuestSetDiscovered(q, true)
	q = CreateQuest()
	QuestSetTitle(q, "伤害预览与敌人状态")
	QuestSetDescription(q, "不点击也能看头顶简短意图：攻击Cola(20)表示攻击Cola、减伤前伤害20。防御(DEF+10)表示增加10护甲，强化(ATK+3)表示增加3攻击。意图数值按原版取整显示，实际结算遵循原规则。施法和打断分别标记。攻击指向自己时写“你”；昵称按完整字符显示；长名省略，同名或缩写相同时附加编号，队友行动点旁显示相同名字。已出手的敌人等待下一轮预告。|n选中敌人时，面板显示具体意图和当前有效的中毒、破甲与虚弱；没有效果就不占空间。切换目标会收起。|n中毒层数按六名玩家分别结算，面板列出合计层数、你的层数和本轮毒伤参考。参考值按当前属性计算，已计增伤、脚本魔抗和暴击范围；护甲、免疫与追击另计。头顶只保留毒层数，毒伤详情在面板查看。" .. "|n上次毒结算净扣血：上一轮六次直接毒伤造成的实际生命净减少，不含稍后触发的追击；没有记录时不显示。|n破甲显示本轮已经降低的护甲量及当前护甲；敌人回合复原护甲后清除。虚弱显示下次攻击降低 30%，攻击预告本身已经计入，不再减第二次。|n鼠标移到技能上查看按当前属性计算的预估。技能说明中保留各自的随机区间、触发条件与资源消耗；预估不额外掷随机数，不提前消耗暴击或精确打击。")
	QuestSetRequired(q, false)
	QuestSetDiscovered(q, true)
	TimerStart(CreateTimer(), 0.02, false, HopeQoL_LoadUIResources)
	TimerStart(CreateTimer(), 0.05, false, HopeQoL_CreateUI)
	TimerStart(CreateTimer(), 0.08, false, HopeGrowth_CreateUI)
	TimerStart(CreateTimer(), 0.2, true, HopeQoL_Refresh)
	q = nil
	chat = nil
	leave = nil
	diagnostic = nil
end


function HopeJob_ShowFrame(frame, visible)
	if frame ~= 0 then
		DzFrameShow(frame, visible)
	end
end
function HopeJob_SetText(frame, value)
	if frame ~= 0 then
		DzFrameSetText(frame, value)
	end
end

function HopeJob_Round()
	return udg_quanshu + 1
end
function HopeJob_AdvancedOpen()
	if udg_quanshu < 2 then
		return false
	end
	if gg_unit_n019_0032 ~= nil and GetUnitTypeId(gg_unit_n019_0032) ~= 0 and not IsUnitHidden(gg_unit_n019_0032) and GetWidgetLife(gg_unit_n019_0032) > 0.405 then
		return true
	end
	return gg_unit_n01C_0003 ~= nil and GetUnitTypeId(gg_unit_n01C_0003) ~= 0 and not IsUnitHidden(gg_unit_n01C_0003) and GetWidgetLife(gg_unit_n01C_0003) > 0.405
end
function HopeJob_InRoom(p)
	local i = GetPlayerId(p) + 1
	local u = udg_hero[i]
	local ok = false
	if i >= 1 and i <= 6 and u ~= nil then
		ok = GetUnitX(u) >= -3328.0 and GetUnitX(u) <= -1800.0 and GetUnitY(u) >= 1800.0 and GetUnitY(u) <= 3072.0 and GetWidgetLife(u) > 0.405 and not udg_ZhandouZhong
	end
	u = nil
	return ok
end

function HopeReclass_First(kind)
	return kind == 1311780932 or kind == 1211117619 or kind == 1211117617 or kind == 1311780919 or kind == 1160785976 or kind == 1311780933 or kind == 1328558129 or kind == 1328558131 or kind == 1213870129
end
function HopeReclass_Can(i)
	return i >= 1 and i <= 6 and udg_hero[i] ~= nil and HopeReclass_First(GetUnitTypeId(udg_hero[i])) and not HopeJob_Awakened[i]
end
function HopeReclass_Training(u)
	if GetUnitTypeId(u) == 1213870129 then
		return GetUnitAbilityLevel(u, 1096435792) * 2
	end
	return 0
end
function HopeReclass_Points(u)
	local kind = GetUnitTypeId(u)
	if kind == 1311780932 then
		return GetUnitAbilityLevel(u, 1093677136)
	elseif kind == 1211117619 then
		return GetUnitAbilityLevel(u, 1093677137)
	elseif kind == 1211117617 then
		return GetUnitAbilityLevel(u, 1093677131)
	elseif kind == 1311780919 then
		return GetUnitAbilityLevel(u, 1093677132)
	elseif kind == 1160785976 then
		return GetUnitAbilityLevel(u, 1093677135)
	elseif kind == 1311780933 then
		return GetUnitAbilityLevel(u, 1093677134) + GetUnitAbilityLevel(u, 1093678167)
	elseif kind == 1328558129 then
		return GetUnitAbilityLevel(u, 1093677395)
	elseif kind == 1328558131 then
		return GetUnitAbilityLevel(u, 1093677653)
	elseif kind == 1213870129 then
		return GetUnitAbilityLevel(u, 1096435792)
	end
	return 0
end
function HopeReclass_Blocker(index, p)
	local i = GetPlayerId(p) + 1
	local u = udg_hero[i]
	local deduction = HopeReclass_Training(u)
	local reason = ""
	if p == nil or i < 1 or i > 6 or not HopeReclass_Can(i) then
		reason = "重新转职仅限已一转、尚未二转的英雄。"
	elseif index < 0 or index >= HopeJob_Count or HopeJob_Stage[index] ~= 1 then
		reason = "无效的重转职业。"
	elseif HopeReclass_Busy[i] then
		reason = "正在重新转职，请稍候。"
	elseif not HopeJob_InRoom(p) then
		reason = "请回到原泉水爬塔房间的一转入口。"
	elseif HopeRoute_RewardPending(i - 1) or HopeChoice_PlayerPending[i - 1] > 0 then
		reason = "请先完成待选奖励。"
	elseif udg_Ls_zj_Str[i] ~= 0 or udg_Ls_zj_Agi[i] ~= 0 or udg_Ls_zj_Int[i] ~= 0 or udg_Linshi_Str[i] ~= 0 or HopeMeditation_Active[i] then
		reason = "请等待临时属性效果结束后再重新转职。"
	elseif index ~= 24 and HopeJob_Target[index] == GetUnitTypeId(u) then
		reason = "你已经是该职业，不会扣除积分。"
	elseif GetHeroStr(u, false) - deduction < HopeJob_Str[index] or GetHeroAgi(u, false) - deduction < HopeJob_Agi[index] or GetHeroInt(u, false) - deduction < HopeJob_Int[index] then
		reason = "移除旧职业修炼后的基础属性不足；装备和临时加成不计。"
	elseif not HopeCloud_CanWrite(p) then
		reason = "存档积分尚未就绪，暂时不能重新转职。"
	elseif udg_Wj_jf[i] < 10 then
		reason = "重新转职需要10存档积分，当前 " .. (I2S(udg_Wj_jf[i]) or "") .. "。"
	end
	u = nil
	return reason
end

function HopeJob_Visible(index, i)
	if index < 0 or index >= HopeJob_Count or i < 1 or i > 6 then
		return false
	end
	if HopeJob_Stage[index] >= 2 and not HopeJob_AdvancedOpen() then
		return false
	end
	if HopeJob_Stage[index] == 1 and HopeReclass_Can(i) then
		return true
	end
	if HopeJob_Awakened[i] and HopeJob_AwakenOption[i] == index then
		return true
	end
	return udg_hero[i] ~= nil and HopeJob_Source[index] == GetUnitTypeId(udg_hero[i]) and (not HopeJob_Awakened[i] or HopeJob_AwakenOption[i] == index)
end
-- Entrance selection is local presentation state; synchronized promotion never reads it.
function HopeJob_InPanel(index, i)
	return HopeJob_Visible(index, i) and (HopeJob_Entry == 1 and HopeJob_Stage[index] == 1 or HopeJob_Entry == 2 and HopeJob_Stage[index] >= 2)
end
function HopeJob_WoodCost(index)
	if index < 0 or index >= HopeJob_Count then
		return 0
	end
	if HopeJob_Stage[index] == 3 then
		return 30
	end
	return 0
end
function HopeThird_StudyBlock(index, owner)
	local p = GetPlayerId(owner) + 1
	if p < 1 or p > 6 or index < 0 or index >= HopeJob_Count then
		return "无效研习。"
	end
	if not HopeJob_Awakened[p] or HopeJob_AwakenOption[p] ~= index or not HopeThird_Passive[index] or udg_hero[p] == nil then
		return "该研习不属于当前三转职业。"
	end
	if not HopeJob_InRoom(owner) then
		return "请回到原泉水房间研习。"
	end
	if HopeRoute_RewardPending(p - 1) then
		return "请先完成待选奖励。"
	end
	if HopeThird_Level(udg_hero[p]) >= 3 then
		return "三转被动已满级（3级）。"
	end
	if HopeThird_Level(udg_hero[p]) < 1 then
		return "尚未获得三转被动。"
	end
	if GetHeroSkillPoints(udg_hero[p]) < 1 then
		return "技能点不足；每次研习消耗1技能点，后续升级可继续获得技能点。"
	end
	return ""
end
function HopeThird_Study(index, owner)
	local p = GetPlayerId(owner) + 1
	local level = 0
	local reason = HopeThird_StudyBlock(index, owner)
	if reason ~= "" then
		DisplayTimedTextToPlayer(owner, 0, 0, 4.0, reason)
		return
	end
	level = HopeThird_Level(udg_hero[p])
	UnitModifySkillPoints(udg_hero[p], -1)
	if SetUnitAbilityLevel(udg_hero[p], HopeThird_Ability[index], level + 1) ~= level + 1 then
		UnitModifySkillPoints(udg_hero[p], 1)
		DisplayTimedTextToPlayer(owner, 0, 0, 4.0, "研习未完成，技能点已退还。")
		return
	end
	DisplayTimedTextToPlayer(owner, 0, 0, 4.0, "三转被动提升至 " .. (I2S(level + 1) or "") .. "/3 级；技能点 -1。")
end
function HopeJob_GoldCost(index)
	if index >= 0 and index < HopeJob_Count and HopeJob_Stage[index] == 3 then
		return 1000
	end
	return 0
end

function HopeJob_Blocker(index, p)
	local i = GetPlayerId(p) + 1
	local u = udg_hero[i]
	local s = ""
	if i >= 1 and i <= 6 and HopeJob_Awakened[i] and index == HopeJob_AwakenOption[i] and HopeThird_Passive[index] then
		u = nil
		return HopeThird_StudyBlock(index, p)
	end
	if index >= 0 and index < HopeJob_Count and HopeJob_Stage[index] == 1 and HopeReclass_Can(i) then
		u = nil
		return HopeReclass_Blocker(index, p)
	end
	if index < 0 or index >= HopeJob_Count or i < 1 or i > 6 then
		s = "无效的转职选项。"
	elseif HopeJob_Stage[index] >= 2 and not HopeJob_AdvancedOpen() then
		s = "二转建筑尚未开放；第3轮出现后才能办理二转或三转。"
	elseif not HopeJob_Visible(index, i) then
		s = "该进阶不属于你的职业路线。"
	elseif HopeJob_Awakened[i] then
		s = "已完成三转，本局不能再次转职。"
	elseif not HopeJob_InRoom(p) then
		s = "请回到原来的泉水爬塔房间。"
	elseif HopeRoute_RewardPending(i - 1) then
		s = "请先完成待选奖励。"
	elseif HopeJob_Stage[index] == 3 and HopeJob_Round() < 4 then
		s = "三转从第4轮开始解锁；完成前3轮即可，不需要通关第4轮。"
	elseif HopeJob_Stage[index] == 3 and GetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER) < HopeJob_WoodCost(index) then
		s = "木材不足：三转需要 " .. (I2S(HopeJob_WoodCost(index)) or "") .. " 木材，当前 " .. (I2S(GetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER)) or "") .. "。"
	elseif HopeJob_Stage[index] == 3 and GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD) < HopeJob_GoldCost(index) then
		s = "金币不足：三转需要1000金币，当前 " .. (I2S(GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD)) or "") .. "。"
	elseif GetHeroLevel(u) < HopeJob_Level[index] then
		s = "等级不足，需要等级 " .. (I2S(HopeJob_Level[index]) or "") .. "。"
	elseif GetHeroStr(u, false) < HopeJob_Str[index] or GetHeroAgi(u, false) < HopeJob_Agi[index] or GetHeroInt(u, false) < HopeJob_Int[index] then
		s = "基础属性不足（装备和临时加成不计）。"
	end
	u = nil
	return s
end
function HopeJob_Close()
	HopeJob_Expanded = false
	HopeJob_ShowFrame(HopeJob_Panel, false)
end
function HopeJob_Show(p, entry)
	if GetPlayerId(p) < 0 or GetPlayerId(p) >= 6 or entry ~= 1 and entry ~= 2 or not HopeJob_InRoom(p) then
		return
	end
	if entry == 2 and not HopeJob_AdvancedOpen() then
		return
	end
	if p == GetLocalPlayer() and GetPlayerId(p) < 6 then
		if HopeGrowth_Pending[GetPlayerId(p)] then
			HopeChoice_Hidden = true
		end
		HopeJob_Entry = entry
		HopeJob_Selected = -1
		HopeJob_Page = 0
		HopeJob_DetailPage = 0
		HopeJob_Expanded = true
		if HopeJob_Expanded then
			HopeLayout_Focus(5)
		end
		HopeQoL_Expanded = false
		HopeArchive_Expanded = false
		HopeGift_Expanded = false
		HopeRelic_Expanded = false
		HopeRoute_Details = false
		HopeJob_ShowFrame(HopeJob_Panel, true)
	end
end
function HopeJob_Open()
	local p = DzGetTriggerUIEventPlayer()
	local entry = 2
	if GetUnitTypeId(udg_hero[GetPlayerId(p) + 1]) == 1211117616 or HopeReclass_Can(GetPlayerId(p) + 1) and not HopeJob_AdvancedOpen() then
		entry = 1
	end
	HopeJob_Show(p, entry)
	p = nil
end
function HopeJob_Select(option)
	HopeJob_Selected = option
	HopeJob_Page = 0
	HopeJob_DetailPage = 0
end
function HopeJob_Page0()
	HopeJob_Page = 0
	HopeJob_DetailPage = 0
end
function HopeJob_Page1()
	HopeJob_Page = 1
	HopeJob_DetailPage = 0
end
function HopeJob_Page2()
	HopeJob_Page = 2
	HopeJob_DetailPage = 0
end
function HopeJob_Prev()
	HopeJob_DetailPage = IMaxBJ(0, HopeJob_DetailPage - 1)
end
function HopeJob_Next()
	local count = 0
	if HopeJob_Selected < 0 then
		return
	end
	if HopeJob_Page == 1 then
		count = HopeJob_SkillCount[HopeJob_Selected]
	elseif HopeJob_Page == 2 then
		count = HopeJob_PassiveCount[HopeJob_Selected]
	end
	HopeJob_DetailPage = IMinBJ(IMaxBJ(0, count - 1), HopeJob_DetailPage + 1)
end
-- Replace only the hidden lineage. Keep ordinary first/second promotions on the original item triggers.
function HopeJob_ReplaceHidden(p, kind)
	local i = GetPlayerId(p) + 1
	local old = udg_hero[i]
	local u = CreateUnit(p, kind, GetUnitX(old), GetUnitY(old), GetUnitFacing(old))
	local slot = 0
	local it = nil
	local aid = 0
	local training = GetUnitAbilityLevel(old, 1096435792)
	if GetUnitTypeId(old) == 1211117616 then
		SetHeroXP(u, 0, false)
	else
		SetHeroXP(u, GetHeroXP(old), false)
	end
	SetHeroStr(u, GetHeroStr(old, false) - udg_Ls_zj_Str[i], true)
	SetHeroAgi(u, GetHeroAgi(old, false) - udg_Ls_zj_Agi[i], true)
	SetHeroInt(u, GetHeroInt(old, false) - udg_Ls_zj_Int[i], true)
	udg_Ls_zj_Str[i] = 0
	udg_Ls_zj_Agi[i] = 0
	udg_Ls_zj_Int[i] = 0
	SetUnitState(u, UNIT_STATE_MAX_LIFE, GetUnitState(old, UNIT_STATE_MAX_LIFE))
	SetUnitState(u, UNIT_STATE_MAX_MANA, GetUnitState(old, UNIT_STATE_MAX_MANA))
	for _ in _loop_() do
		if slot >= 6 then break end
		it = UnitItemInSlot(old, slot)
		if it ~= nil then
			UnitRemoveItem(old, it)
			UnitAddItem(u, it)
		end
		slot = slot + 1
	end
	aid = LoadInteger(YDHT, i, 1093503686)
	if aid ~= 0 then
		UnitAddAbility(u, aid)
	end
	aid = LoadInteger(YDHT, i, 1068628448)
	if aid ~= 0 then
		UnitAddAbility(u, aid)
	end
	aid = LoadInteger(YDHT, i, 1494149627)
	if aid ~= 0 then
		UnitAddAbility(u, aid)
	end
	if udg_R_Skill[i] ~= 0 and udg_R_Skill[i] ~= 1093677388 then
		UnitAddAbility(u, udg_R_Skill[i])
	end
	SetUnitState(u, ConvertUnitState(18), GetUnitState(u, ConvertUnitState(18)) + I2R(udg_Gongjili_Jc[i]))
	udg_Minjie_jiaGong[i] = 0
	SetUnitMoveSpeed(u, GetUnitMoveSpeed(old))
	if GetUnitTypeId(old) ~= 1211117616 then
		if training > 0 then
			UnitAddAbility(u, 1096435792)
			SetUnitAbilityLevel(u, 1096435792, training)
			UnitMakeAbilityPermanent(u, true, 1096435792)
		end
		UnitModifySkillPoints(u, GetHeroSkillPoints(old) - GetHeroSkillPoints(u))
	end
	udg_hero[i] = u
	RemoveUnit(old)
	SetUnitState(u, UNIT_STATE_LIFE, GetUnitState(u, UNIT_STATE_MAX_LIFE))
	SetUnitState(u, UNIT_STATE_MANA, GetUnitState(u, UNIT_STATE_MAX_MANA))
	SelectUnitForPlayerSingle(u, p)
	old = nil
	u = nil
	it = nil
end
function HopeJob_AddStats(i, strength, agility, intelligence)
	SetHeroStr(udg_hero[i], GetHeroStr(udg_hero[i], false) + strength, true)
	SetHeroAgi(udg_hero[i], GetHeroAgi(udg_hero[i], false) + agility, true)
	SetHeroInt(udg_hero[i], GetHeroInt(udg_hero[i], false) + intelligence, true)
end
function HopeThird_Unlock(index, p)
	local u = udg_hero[p]
	local aid = HopeThird_Ability[index]
	local old = 1096430385
	for _ in _loop_() do
		if old > 1096430390 then break end
		if old ~= aid then
			UnitRemoveAbility(u, old)
		end
		old = old + 1
	end
	UnitAddAbility(u, aid)
	SetUnitAbilityLevel(u, aid, 1)
	UnitMakeAbilityPermanent(u, true, aid)
	u = nil
end

