	elseif id == 1093677386 then
		return "增加英雄2点行动值|n同时扣除自身999点护甲|n每回合限用一次"
	elseif id == 1093677387 then
		return "向敌人冲锋|n造成力量*4的伤害值|n如果敌人行为是防御或强化攻击则打断其动作并且伤|n害翻倍|n每回合限用一次"
	elseif id == 1093677390 then
		return "增加周围友军单位30%的攻击力。|n持续30秒。|n每回合限用一次"
	elseif id == 1093677391 then
		return "减少目标单位15点的护甲 |n每回合限用一次|n(目标护甲为负时技能无效）"
	elseif id == 1093677616 then
		return "英雄暴击率+15% 暴击伤害+50%"
	elseif id == 1093677617 then
		return "跳跃过去对目标区域内的所有单位造成力量*3.5的|n物理伤害|n行动点消耗:1|n每回合限用一次"
	elseif id == 1093677890 then
		return "万箭齐发，对所有敌人造成 英雄敏捷*1.5的物理|n伤害|n行动点消耗:1|n每点敏捷增加该伤害1%"
	elseif id == 1093677891 then
		return "对敌人释放一次混沌打击，造成物理伤害|n基础伤害值：攻击力*5|n浮动值1%-300% |n(该浮动不会因为力量敏捷专注而改变)|n行动点消耗:2|n每回合限用一次"
	elseif id == 1093677913 then
		return "消耗所有MP，对敌人造成巨量物理伤害|n基础伤害值：力量*7.5*（1+消耗魔法值/25)|n行动点消耗:3|n每回合限用一次"
	elseif id == 1093677914 then
		return "召唤6颗陨石随机对范围内敌人造成法术伤害|n每颗陨石伤害值：智力*3|n行动点消耗:2|n每回合限用一次"
	elseif id == 1093678133 then
		return "瞬移到敌人身后对其造成物理伤害|n该伤害必定暴击|n基础伤害值：敏捷值*5+攻击力*2|n行动点消耗：2|n每回合限定使用一次|n每点敏捷增加该伤害1%"
	end
	return HopeSkill_Original(id, 1)
end
function HopeCompact_RRefresh(i, d, abilityId)
	local owner = GetPlayerId(GetLocalPlayer()) + 1
	local current = "无"
	if HopeR_Key ~= abilityId or HopeR_Current ~= udg_R_Skill[owner] then
		HopeR_Key = abilityId
		HopeR_Current = udg_R_Skill[owner]
		HopeR_Count = 0
		HopeR_Offset = 0
		if udg_R_Skill[owner] ~= 0 then
			current = GetAbilityName(udg_R_Skill[owner])
		end
		HopeScroll_Add(2, "当前：" .. (current or "") .. "|n新技能：" .. (GetAbilityName(abilityId) or ""))
		HopeScroll_Add(2, HopeCompact_RText(abilityId))
	end
	HopeR_Active = i
	HopeJob_SetText(HopeModern_Title[i], "替换 R 技能")
	HopeJob_SetText(HopeR_Body[i], HopeScroll_View(2, HopeR_Offset, 5))
	HopeJob_SetText(HopeR_Notice[i], "放弃不退费用 · 滚轮/上下按钮查看详情")
end

function HopeModern_Refresh()
	local i = 1
	local j = 1
	local owner = GetPlayerId(GetLocalPlayer())
	local newest = 0
	local h = 0
	local abilityId = 0
	local d = nil
	local show = false
	local title = ""
	local detail = "选择后立即生效；收起 F6 可先查看角色资料。"
	HopeModern_Tick = HopeModern_Tick + 1
	HopeR_Active = 0
	if not HopeModern_Ready then
		return
	end
	for _ in _loop_() do
		if i > HopeChoice_DialogCount then break end
		if HopeChoice_DialogPending[i] and HopeChoice_Owner[i] == owner then
			newest = i
		end
		i = i + 1
	end
	i = 1
	for _ in _loop_() do
		if i > 13 then break end
		show = i == newest and not HopeChoice_Hidden and not HopeGrowth_Pending[owner] and not HopeRoute_Assigning
		HopeJob_ShowFrame(HopeModern_Panel[i], show)
		if show then
			d = HopeChoice_Dialog[i]
			h = GetHandleId(d)
			title = LoadStr(HopeModern_Data, h, 100)
			if d == udg_Rskill_shifoutihuan[owner + 1] then
				abilityId = LoadInteger(YDHT, h, -711261722)
				title = "替换 R 技能：" .. (GetAbilityName(abilityId) or "")
				detail = "当前：" .. (GetAbilityName(udg_R_Skill[owner + 1]) or "") .. "|n新技能：" .. (HopeSkill_Original(abilityId, 1) or "") .. "|n放弃不退还本次购买费用。"
			elseif d == udg_Youxi_ND_XZ then
				detail = "简单/普通：3轮；困难/极难：4轮。|n炼狱：5轮；无限挑战：无限轮。|n选定难度后，再指定本局的路线选择者。"
			else
				detail = "消耗的升级点已结算；以下奖励三选一。|n放弃不返还升级点；收起 F6 保留当前选项。"
			end
			HopeJob_SetText(HopeModern_Title[i], title)
			HopeJob_SetText(HopeModern_Description[i], detail)
			j = 1
			for _ in _loop_() do
				if j > 6 then break end
				HopeJob_ShowFrame(HopeModern_Row[i * 8 + j], j <= LoadInteger(HopeModern_Data, h, 0))
				HopeJob_SetText(HopeModern_Row[i * 8 + j], LoadStr(HopeModern_Data, h, j))
				j = j + 1
			end
			HopeLayout_Choice(i, d)
			if d == udg_Rskill_shifoutihuan[owner + 1] then
				HopeCompact_RRefresh(i, d, abilityId)
			end
		end
		i = i + 1
	end
	d = nil
end
